export default [{"id":"790","jozz":"7","page":"128","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"3","line_end":"4","aya_no":"1","aya_text":"ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ يَعۡدِلُونَ","aya_text_emlaey":"الحمد لله الذي خلق السموات والأرض وجعل الظلمات والنور ثم الذين كفروا بربهم يعدلون","aya_tafseer":"[1] الثناء على الله بصفاته التي كلُّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، الذي أنشأ السموات والأرض وما فيهن، وخلق الظلماتِ والنورَ ، وذلك بتعاقب الليل والنهار. وفي هذا دلالة على عظمة الله تعالى، واستحقاقه وحده العبادة، فلا يجوز لأحد أن يشرك به غيره. ومع هذا الوضوح فإن الكافرين يسوون بالله غيره، ويشركون به."},{"id":"791","jozz":"7","page":"128","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"6","aya_no":"2","aya_text":"هُوَ ٱلَّذِي خَلَقَكُم مِّن طِينٖ ثُمَّ قَضَىٰٓ أَجَلٗاۖ وَأَجَلٞ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ","aya_text_emlaey":"هو الذي خلقكم من طين ثم قضى أجلا وأجل مسمى عنده ثم أنتم تمترون","aya_tafseer":"[2] هو الذي خلق أباكم آدمَ من طين وأنتم سلالة منه، ثم كتب مدة بقائكم في هذه الحياة الدنيا، وكتب أجلاً آخر محدَّداً لا يعلمه إلا هو جل وعلا، وهو يوم القيامة، ثم أنتم بعد هذا تشكُّون في قدرة الله تعالى على البعث بعد الموت."},{"id":"792","jozz":"7","page":"128","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"7","aya_no":"3","aya_text":"وَهُوَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَفِي ٱلۡأَرۡضِ يَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ وَيَعۡلَمُ مَا تَكۡسِبُونَ","aya_text_emlaey":"وهو الله في السموات وفي الأرض يعلم سركم وجهركم ويعلم ما تكسبون","aya_tafseer":"[3] والله سبحانه هو الإله المعبود بحقٍّ في السموات والأرض. ومن دلائل ألوهيته أنه يعلم جميع ما تخفونه -أيها الناس- وما تعلنونه، ويعلم جميع أعمالكم من خير أو شر؛ ولهذا فإنه -جلَّ وعلا- وحده هو الإله المستحق للعبادة."},{"id":"793","jozz":"7","page":"128","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"8","aya_no":"4","aya_text":"وَمَا تَأۡتِيهِم مِّنۡ ءَايَةٖ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا مُعۡرِضِينَ","aya_text_emlaey":"وما تأتيهم من آية من آيات ربهم إلا كانوا عنها معرضين","aya_tafseer":"[4] هؤلاء الكفار الذين يشركون مع الله تعالى غيره قد جاءتهم الحجج الواضحة والدلالات البينة على وحدانية الله -جل وعلا-، وصِدْقِ محمد -صلى الله عليه وسلم- في نبوته وما جاء به، ولكن ما إن جاءتهم حتى أعرضوا عن قَبولها، ولم يؤمنوا بها."},{"id":"794","jozz":"7","page":"128","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"8","line_end":"9","aya_no":"5","aya_text":"فَقَدۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَسَوۡفَ يَأۡتِيهِمۡ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ","aya_text_emlaey":"فقد كذبوا بالحق لما جاءهم فسوف يأتيهم أنباء ما كانوا به يستهزئون","aya_tafseer":"[5] لقد جحد هؤلاء الكفار الحقَّ الذي جاءهم به محمد -صلى الله عليه وسلم- وسخروا من دعاته؛ جهلاً منهم بالله واغتراراً بإمهاله إياهم، فسوف يرون ما استهزؤوا به أنه الحق والصدق، ويبين الله للمكذبين كذبهم وافتراءهم، وسيجازيهم عليه."},{"id":"795","jozz":"7","page":"128","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"13","aya_no":"6","aya_text":"أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنٖ مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَآءَ عَلَيۡهِم مِّدۡرَارٗا وَجَعَلۡنَا ٱلۡأَنۡهَٰرَ تَجۡرِي مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ","aya_text_emlaey":"ألم يروا كم أهلكنا من قبلهم من قرن مكناهم في الأرض ما لم نمكن لكم وأرسلنا السماء عليهم مدرارا وجعلنا الأنهار تجري من تحتهم فأهلكناهم بذنوبهم وأنشأنا من بعدهم قرنا آخرين","aya_tafseer":"[6] ألم يعلم هؤلاء الذين يجحدون وحدانية الله تعالى واستحقاقَه وحدَه العبادة، ويُكذِّبون رسوله محمداً -صلى الله عليه وسلم- ما حلَّ بالأمم المكذبة قبلهم من هلاك وتدمير، وقد مكنَّاهم في الأرض ما لم نمكن لكم أيها الكافرون، وأنعمنا عليهم بإنزال الأمطار وجريان الأنهار من تحت مساكنهم؛ استدراجاً وإملاء لهم، فكفروا بنعم الله وكذبوا الرسل، فأهلكناهم بسبب ذنوبهم، وأنشأنا من بعدهم أمماً أخرى خلفوهم في عمارة الأرض؟"},{"id":"796","jozz":"7","page":"128","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"14","aya_no":"7","aya_text":"وَلَوۡ نَزَّلۡنَا عَلَيۡكَ كِتَٰبٗا فِي قِرۡطَاسٖ فَلَمَسُوهُ بِأَيۡدِيهِمۡ لَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ","aya_text_emlaey":"ولو نـزلنا عليك كتابا في قرطاس فلمسوه بأيديهم لقال الذين كفروا إن هذا إلا سحر مبين","aya_tafseer":"[7] ولو نَزَّلنا عليك -أيها الرسول- كتاباً من السماء في أوراق فلمسه هؤلاء المشركون بأيديهم لقالوا: إنَّ ما جئت به -أيها الرسول- سحر واضح بيِّن."},{"id":"797","jozz":"7","page":"128","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"14","line_end":"15","aya_no":"8","aya_text":"وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ مَلَكٞۖ وَلَوۡ أَنزَلۡنَا مَلَكٗا لَّقُضِيَ ٱلۡأَمۡرُ ثُمَّ لَا يُنظَرُونَ","aya_text_emlaey":"وقالوا لولا أنـزل عليه ملك ولو أنـزلنا ملكا لقضي الأمر ثم لا ينظرون","aya_tafseer":"[8] وقال هؤلاء المشركون: هلَّا أنزل الله تعالى على محمد مَلَكاً من السماء؛ ليصدقه فيما جاء به من النبوة، ولو أنزلنا مَلَكاً من السماء إجابةً لطلبهم لقُضِي الأمر بإهلاكهم، ثم لا يُمْهلون لتوبة؛ فقد سبق في علم الله أنهم لا يؤمنون."},{"id":"798","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"9","aya_text":"وَلَوۡ جَعَلۡنَٰهُ مَلَكٗا لَّجَعَلۡنَٰهُ رَجُلٗا وَلَلَبَسۡنَا عَلَيۡهِم مَّا يَلۡبِسُونَ","aya_text_emlaey":"ولو جعلناه ملكا لجعلناه رجلا وللبسنا عليهم ما يلبسون","aya_tafseer":"[9] ولو جعلنا الرسول المرسل إليهم مَلَكاً إذ لم يقتنعوا بمحمد -صلى الله عليه وسلم-، لجعلنا ذلك الملك في صورة البشر؛ حتى يستطيعوا السماع منه ومخاطبته؛ إذ ليس بإمكانهم رؤية الملك على صورته الملائكية، ولو جاءهم الملك بصورة رجل لاشتبه الأمر عليهم، كما اشتبه عليهم أمر محمد -صلى الله عليه وسلم-."},{"id":"799","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"3","aya_no":"10","aya_text":"وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ","aya_text_emlaey":"ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون","aya_tafseer":"[10] ولمَّا كان طلبهم إنزال الملك على سبيل الاستهزاء بمحمد -صلى الله عليه وسلم-، بيَّن الله تعالى له أن الاستهزاء بالرسل عليهم السلام ليس أمراً حادثاً، بل قد وقع من الكفار السابقين مع أنبيائهم، فأحاط بهم العذاب الذي كانوا يهزؤون به وينكرون وقوعه."},{"id":"800","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"3","line_end":"4","aya_no":"11","aya_text":"قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ ثُمَّ ٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ","aya_text_emlaey":"قل سيروا في الأرض ثم انظروا كيف كان عاقبة المكذبين","aya_tafseer":"[11] قل لهم -أيها الرسول-: سيروا في الأرض ثم انظروا كيف أعقب الله المكذبين الهلاك والخزي؟ فاحذروا مثل مصارعهم، وخافوا أن يحلَّ بكم مثلُ الذي حل بهم."},{"id":"801","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"7","aya_no":"12","aya_text":"قُل لِّمَن مَّا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۚ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ","aya_text_emlaey":"قل لمن ما في السموات والأرض قل لله كتب على نفسه الرحمة ليجمعنكم إلى يوم القيامة لا ريب فيه الذين خسروا أنفسهم فهم لا يؤمنون","aya_tafseer":"[12] قل -أيها الرسول- لهؤلاء المشركين: لمن مُلكُ السموات والأرض وما فيهن؟ قل: هو لله كما تُقِرُّون بذلك وتعلمونه، فاعبدوه وحده. كتب الله على نفسه الرحمة فلا يعجل على عباده بالعقوبة. ليجمعنكم إلى يوم القيامة الذي لا شك فيه للحساب والجزاء. الذين أشركوا بالله أهلكوا أنفسهم؛ فهم لا يوحدون الله، ولا يصدقون بوعده ووعيده، ولا يقرون بنبوة محمد -صلى الله عليه وسلم-."},{"id":"802","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"8","aya_no":"13","aya_text":"۞ وَلَهُۥ مَا سَكَنَ فِي ٱلَّيۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","aya_text_emlaey":"وله ما سكن في الليل والنهار وهو السميع العليم","aya_tafseer":"[13] ولله ملك كل شيء في السموات والأرض، سكن أو تحرك، خفي أو ظهر، الجميع عبيده وخلقه، وتحت قهره وتصرفه وتدبيره، وهو السميع لأقوال عباده، العليم بسرائرهم وأعمالهم."},{"id":"803","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"8","line_end":"11","aya_no":"14","aya_text":"قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ وَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"قل أغير الله أتخذ وليا فاطر السموات والأرض وهو يطعم ولا يطعم قل إني أمرت أن أكون أول من أسلم ولا تكونن من المشركين","aya_tafseer":"[14] قل -أيها الرسول- لهؤلاء المشركين مع الله تعالى غيره: أغير الله تعالى أتخذ ولياً ونصيراً، وهو خالق السموات والأرض وما فيهن، وهو الذي يرزق خلقه ولا يرزقه أحد؟ قل -أيها الرسول-: إني أُمِرْت أن أكون أول مَن خضع وانقاد له بالعبودية من هذه الأمة، ونُهيت أن أكون من المشركين معه غيره."},{"id":"804","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"11","line_end":"12","aya_no":"15","aya_text":"قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ","aya_text_emlaey":"قل إني أخاف إن عصيت ربي عذاب يوم عظيم","aya_tafseer":"[15] قل -أيها الرسول- لهؤلاء المشركين مع الله غيره: إني أخاف إن عصيت ربي، فخالفت أمره، وأشركت معه غيره في عبادته، أن ينزل بي عذاب عظيم يوم القيامة."},{"id":"805","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"13","aya_no":"16","aya_text":"مَّن يُصۡرَفۡ عَنۡهُ يَوۡمَئِذٖ فَقَدۡ رَحِمَهُۥۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡمُبِينُ","aya_text_emlaey":"من يصرف عنه يومئذ فقد رحمه وذلك الفوز المبين","aya_tafseer":"[16] من يصرف الله عنه ذلك العذاب الشديد فقد رحمه، وذلك الصرف هو الظفر البين بالنجاة من العذاب العظيم."},{"id":"806","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"14","aya_no":"17","aya_text":"وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"وإن يمسسك الله بضر فلا كاشف له إلا هو وإن يمسسك بخير فهو على كل شيء قدير","aya_tafseer":"[17] وإن يصبك الله تعالى -أيها الإنسان- بشيء يضرك كالفقر والمرض فلا كاشف له إلا هو، وإن يصبك بخير كالغنى والصحة فلا راد لفضله ولا مانع لقضائه، فهو -جل وعلا- القادر على كل شيء."},{"id":"807","jozz":"7","page":"129","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"15","line_end":"15","aya_no":"18","aya_text":"وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ","aya_text_emlaey":"وهو القاهر فوق عباده وهو الحكيم الخبير","aya_tafseer":"[18] والله سبحانه هو الغالب القاهر فوق عباده؛ خضعت له الرقاب وذَلَّتْ له الجبابرة، وهو الحكيم الذي يضع الأشياء مواضعها وَفْق حكمته، الخبير الذي لا يخفى عليه شيء. ومن اتصف بهذه الصفات يجب ألَّا يشرَك به. وفي هذه الآية إثبات الفوقية لله -تعالى- على جميع خلقه، فوقية مطلقة تليق بجلاله سبحانه."},{"id":"808","jozz":"7","page":"130","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"4","aya_no":"19","aya_text":"قُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةٗۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَئِنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخۡرَىٰۚ قُل لَّآ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَإِنَّنِي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ","aya_text_emlaey":"قل أي شيء أكبر شهادة قل الله شهيد بيني وبينكم وأوحي إلي هذا القرآن لأنذركم به ومن بلغ أئنكم لتشهدون أن مع الله آلهة أخرى قل لا أشهد قل إنما هو إله واحد وإنني بريء مما تشركون","aya_tafseer":"[19] قل -أيها الرسول لهؤلاء المشركين-: أيُّ شيء أعظم شهادة في إثبات صدقي فيما أخبرتكم به أني رسول الله؟ قل: الله شهيد بيني وبينكم، أي: هو العالم بما جئتكم به وما أنتم قائلون لي، وأوحى الله إليَّ هذا القرآن مِن أجل أن أنذركم به عذابَه أن يحلَّ بكم، وأُنذِرَ به مَن وصل إليه من الأمم. إنكم لَتقرون أن مع الله معبودات أخرى تشركونها به. قل لهم -أيها الرسول-: إني لا أشهد على ما أقررتم به، إنما الله إله واحد لا شريك له، وإنني بريء من كل شريك تعبدونه معه."},{"id":"809","jozz":"7","page":"130","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"5","aya_no":"20","aya_text":"ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمُۘ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فَهُمۡ لَا يُؤۡمِنُونَ","aya_text_emlaey":"الذين آتيناهم الكتاب يعرفونه كما يعرفون أبناءهم الذين خسروا أنفسهم فهم لا يؤمنون","aya_tafseer":"[20] الذين آتيناهم التوراة والإنجيل، يعرفون محمداً -صلى الله عليه وسلم- بصفاته المكتوبة عندهم كمعرفتهم أبناءهم، فكما أن أبناءهم لا يشتبهون أمامهم بغيرهم، فكذلك محمد -صلى الله عليه وسلم- لا يشتبه بغيره لدقة وصفه في كتبهم، ولكنهم اتبعوا أهواءهم، فخسروا أنفسهم حين كفروا بمحمد -صلى الله عليه وسلم- وبما جاء به."},{"id":"810","jozz":"7","page":"130","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"6","aya_no":"21","aya_text":"وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ","aya_text_emlaey":"ومن أظلم ممن افترى على الله كذبا أو كذب بآياته إنه لا يفلح الظالمون","aya_tafseer":"[21] لا أحد أشد ظلماً ممَّن تَقَوَّلَ الكذب على الله تعالى، فزعم أن له شركاء في العبادة، أو ادَّعى أن له ولداً أو صاحبة، أو كذَّب ببراهينه وأدلته التي أيَّد بها رسله عليهم السلام. إنه لا يفلح الظالمون الذين افتَرَوا الكذب على الله، ولا يظفرون بمطالبهم في الدنيا ولا في الآخرة."},{"id":"811","jozz":"7","page":"130","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"7","aya_no":"22","aya_text":"وَيَوۡمَ نَحۡشُرُهُمۡ جَمِيعٗا ثُمَّ نَقُولُ لِلَّذِينَ أَشۡرَكُوٓاْ أَيۡنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ","aya_text_emlaey":"ويوم نحشرهم جميعا ثم نقول للذين أشركوا أين شركاؤكم الذين كنتم تزعمون","aya_tafseer":"[22] وليحذر هؤلاء المشركون المكذبون بآيات الله تعالى يوم نحشرهم ثم نقول لهم: أين آلهتكم التي كنتم تدَّعون أنهم شركاء مع الله تعالى ليشفعوا لكم؟"},{"id":"812","jozz":"7","page":"130","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"8","line_end":"8","aya_no":"23","aya_text":"ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّآ أَن قَالُواْ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِينَ","aya_text_emlaey":"ثم لم تكن فتنتهم إلا أن قالوا والله ربنا ما كنا مشركين","aya_tafseer":"[23] ثم لم تكن إجابتهم حين فُتِنوا واختُبِروا بالسؤال عن شركائهم إلا أن تبرؤوا منهم، وأقسموا بالله ربِّهم إنهم لم يكونوا مشركين مع الله غيره."},{"id":"813","jozz":"7","page":"130","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"9","aya_no":"24","aya_text":"ٱنظُرۡ كَيۡفَ كَذَبُواْ عَلَىٰٓ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ","aya_text_emlaey":"انظر كيف كذبوا على أنفسهم وضل عنهم ما كانوا يفترون","aya_tafseer":"[24] تأمل -أيها الرسول- كيف كذب هؤلاء المشركون على أنفسهم، وهم في الآخرة قد تبرؤوا من الشرك؟ وذهب وغاب عنهم ما كانوا يظنونه من شفاعة آلهتهم."},{"id":"814","jozz":"7","page":"130","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"13","aya_no":"25","aya_text":"وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَاۖ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"ومنهم من يستمع إليك وجعلنا على قلوبهم أكنة أن يفقهوه وفي آذانهم وقرا وإن يروا كل آية لا يؤمنوا بها حتى إذا جاءوك يجادلونك يقول الذين كفروا إن هذا إلا أساطير الأولين","aya_tafseer":"[25] ومن هؤلاء المشركين مَن يستمع إليك القرآن -أيها الرسول-، فلا يصل إلى قلوبهم؛ لأنهم بسبب اتباعهم أهواءهم جعلنا على قلوبهم أغطية؛ لئلا يفقهوا القرآن، وجعلنا في آذانهم ثِقَلاً وصمماً فلا تسمع ولا تعي شيئاً، وإن يروا الآياتِ الكثيرةَ الدالَّةَ على صدق محمد -صلى الله عليه وسلم- لا يصدقوا بها، حتى إذا جاؤوك -أيها الرسول- بعد معاينة الآيات الدالة على صدقك يخاصمونك: يقول الذين جحدوا آيات الله: ما هذا الذي نسمع إلا ما تناقله الأولون من حكايات لا حقيقة لها."},{"id":"815","jozz":"7","page":"130","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"14","aya_no":"26","aya_text":"وَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡـَٔوۡنَ عَنۡهُۖ وَإِن يُهۡلِكُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ","aya_text_emlaey":"وهم ينهون عنه وينأون عنه وإن يهلكون إلا أنفسهم وما يشعرون","aya_tafseer":"[26] وهؤلاء المشركون ينهَوْن الناس عن اتباع محمد -صلى الله عليه وسلم- والاستماع إليه، ويبتعدون بأنفسهم عنه، وما يهلكون -بصدهم عن سبيل الله- إلا أنفسهم، وما يحسون أنهم يعملون لهلاكها."},{"id":"816","jozz":"7","page":"130","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"14","line_end":"15","aya_no":"27","aya_text":"وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَى ٱلنَّارِ فَقَالُواْ يَٰلَيۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"ولو ترى إذ وقفوا على النار فقالوا ياليتنا نرد ولا نكذب بآيات ربنا ونكون من المؤمنين","aya_tafseer":"[27] ولو ترى -أيها الرسول- هؤلاء المشركين يوم القيامة لرأيت أمراً عظيماً، وذلك حين يُحْبَسون على النار، ويشاهدون ما فيها من السلاسل والأغلال، ورأوا بأعينهم تلك الأمور العظام والأهوال، فعند ذلك قالوا: يا ليتنا نعاد إلى الحياة الدنيا، فنصدق بآيات الله ونعمل بها، ونكونَ من المؤمنين."},{"id":"817","jozz":"7","page":"131","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"28","aya_text":"بَلۡ بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ","aya_text_emlaey":"بل بدا لهم ما كانوا يخفون من قبل ولو ردوا لعادوا لما نهوا عنه وإنهم لكاذبون","aya_tafseer":"[28] ليس الأمر كذلك، بل ظهر لهم يومَ القيامة ما كانوا يعلمونه من أنفسهم من صدق ما جاءت به الرسل في الدنيا، وإن كانوا يُظهرون لأتباعهم خلافه. ولو فرض أن أعيدوا إلى الدنيا فأُمهلوا لرجعوا إلى العناد بالكفر والتكذيب. وإنهم لكاذبون في قولهم: لو رُددنا إلى الدنيا لم نُكذِّب بآيات ربنا، وكنا من المؤمنين."},{"id":"818","jozz":"7","page":"131","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"3","aya_no":"29","aya_text":"وَقَالُوٓاْ إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ","aya_text_emlaey":"وقالوا إن هي إلا حياتنا الدنيا وما نحن بمبعوثين","aya_tafseer":"[29] وقال هؤلاء المشركون المنكرون للبعث: ما الحياة إلا هذه الحياة التي نحن فيها، وما نحن بمبعوثين بعد موتنا."},{"id":"819","jozz":"7","page":"131","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"3","line_end":"4","aya_no":"30","aya_text":"وَلَوۡ تَرَىٰٓ إِذۡ وُقِفُواْ عَلَىٰ رَبِّهِمۡۚ قَالَ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۚ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ","aya_text_emlaey":"ولو ترى إذ وقفوا على ربهم قال أليس هذا بالحق قالوا بلى وربنا قال فذوقوا العذاب بما كنتم تكفرون","aya_tafseer":"[30] ولو ترى -أيها الرسول- منكري البعث إذ حُبسوا بين يدي الله تعالى لقضائه فيهم يوم القيامة، لرأيت أسوأ حال، إذ يقول الله جل وعلا: أليس هذا بالحق، أي: أليس هذا البعث الذي كنتم تنكرونه في الدنيا حقّاً؟ قالوا: بلى وربِّنا إنه لحق، قال الله تعالى: فذوقوا العذاب بما كنتم تكفرون، أي: العذاب الذي كنتم تكذبون به في الدنيا؛ بسبب جحودكم بالله تعالى ورسوله محمد -صلى الله عليه وسلم-."},{"id":"820","jozz":"7","page":"131","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"7","aya_no":"31","aya_text":"قَدۡ خَسِرَ ٱلَّذِينَ كَذَّبُواْ بِلِقَآءِ ٱللَّهِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمُ ٱلسَّاعَةُ بَغۡتَةٗ قَالُواْ يَٰحَسۡرَتَنَا عَلَىٰ مَا فَرَّطۡنَا فِيهَا وَهُمۡ يَحۡمِلُونَ أَوۡزَارَهُمۡ عَلَىٰ ظُهُورِهِمۡۚ أَلَا سَآءَ مَا يَزِرُونَ","aya_text_emlaey":"قد خسر الذين كذبوا بلقاء الله حتى إذا جاءتهم الساعة بغتة قالوا ياحسرتنا على ما فرطنا فيها وهم يحملون أوزارهم على ظهورهم ألا ساء ما يزرون","aya_tafseer":"[31] قد خسر الكفار الذين أنكروا البعث بعد الموت، حتى إذا قامت القيامة وفوجئوا بسوء المصير، نادَوا على أنفسهم بالحسرة على ما ضيَّعوه في حياتهم الدنيا، وهم يحملون آثامهم على ظهورهم، فما أسوأ الأحمال الثقيلة السيئة التي يحملونها!"},{"id":"821","jozz":"7","page":"131","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"8","aya_no":"32","aya_text":"وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبٞ وَلَهۡوٞۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرٞ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"وما الحياة الدنيا إلا لعب ولهو وللدار الآخرة خير للذين يتقون أفلا تعقلون","aya_tafseer":"[32] وما الحياة الدنيا في غالب أحوالها إلا غرور وباطل، والعمل الصالح للدار الآخرة خير للذين يخشون الله، فيتقون عذابه بطاعته واجتناب معاصيه. أفلا تعقلون -أيها المشركون المغترون بزينة الحياة الدنيا- فتُقدِّموا ما يبقى على ما يفنى؟"},{"id":"822","jozz":"7","page":"131","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"10","aya_no":"33","aya_text":"قَدۡ نَعۡلَمُ إِنَّهُۥ لَيَحۡزُنُكَ ٱلَّذِي يَقُولُونَۖ فَإِنَّهُمۡ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ","aya_text_emlaey":"قد نعلم إنه ليحزنك الذي يقولون فإنهم لا يكذبونك ولكن الظالمين بآيات الله يجحدون","aya_tafseer":"[33] إنا نعلم إنه ليُدْخل الحزنَ إلى قلبك تكذيبُ قومك لك في الظاهر، فاصبر واطمئن؛ فإنهم لا يكذبونك في قرارة أنفسهم، بل يعتقدون صدقك، ولكنهم لظلمهم وعدوانهم يجحدون البراهين الواضحة على صدقك، فيكذبونك فيما جئت به."},{"id":"823","jozz":"7","page":"131","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"12","aya_no":"34","aya_text":"وَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِۚ وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"ولقد كذبت رسل من قبلك فصبروا على ما كذبوا وأوذوا حتى أتاهم نصرنا ولا مبدل لكلمات الله ولقد جاءك من نبإ المرسلين","aya_tafseer":"[34] ولقد كذَّب الكفار رسلاً من قبلك أرسلهم الله تعالى إلى أممهم وأوذوا في سبيله، فصبروا على ذلك ومضَوْا في دعوتهم وجهادهم حتى أتاهم نَصْرُ الله. ولا مبدل لكلمات الله، وهي ما أنزل على نبيه محمد -صلى الله عليه وسلم- مِن وعده إياه بالنصر على مَن عاداه. ولقد جاءك -أيها الرسول- مِن خبر مَن كان قبلك من الرسل، وما تحقق لهم مِن نصر الله، وما جرى على مكذبيهم من نقمة الله منهم وغضبه عليهم، فلك فيمن تقدم من الرسل أسوة وقدوة. وفي هذا تسلية للرسول -صلى الله عليه وسلم-."},{"id":"824","jozz":"7","page":"131","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"15","aya_no":"35","aya_text":"وَإِن كَانَ كَبُرَ عَلَيۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِيَ نَفَقٗا فِي ٱلۡأَرۡضِ أَوۡ سُلَّمٗا فِي ٱلسَّمَآءِ فَتَأۡتِيَهُم بِـَٔايَةٖۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَٰهِلِينَ","aya_text_emlaey":"وإن كان كبر عليك إعراضهم فإن استطعت أن تبتغي نفقا في الأرض أو سلما في السماء فتأتيهم بآية ولو شاء الله لجمعهم على الهدى فلا تكونن من الجاهلين","aya_tafseer":"[35] وإن كان عَظُمَ عليك -أيها الرسول- صدود هؤلاء المشركين وانصرافُهم عن الاستجابة لدعوتك، فإن استطعت أن تتخذ نفقاً في الأرض، أو مِصْعَداً تصعد فيه إلى السماء، فتأتيهم بعلامة وبرهان على صحة قولك غير الذي جئناهم به فافعل. ولو شاء الله لَجَمعهم على الهدى الذي أنتم عليه ووفَّقهم للإيمان، ولكن لم يشأ ذلك لحكمة يعلمها سبحانه، فلا تكونن -أيها الرسول- من الجاهلين الذين اشتد حزنهم، وتحسَّروا حتى أوصلهم ذلك إلى الجزع الشديد."},{"id":"825","jozz":"7","page":"132","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"36","aya_text":"۞ إِنَّمَا يَسۡتَجِيبُ ٱلَّذِينَ يَسۡمَعُونَۘ وَٱلۡمَوۡتَىٰ يَبۡعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيۡهِ يُرۡجَعُونَ","aya_text_emlaey":"إنما يستجيب الذين يسمعون والموتى يبعثهم الله ثم إليه يرجعون","aya_tafseer":"[36] إنما يجيبك -أيها الرسول- إلى ما دعوت إليه من الهدى الذين يسمعون الكلام سماع قَبول. أما الكفار فهم في عداد الموتى؛ لأن الحياة الحقيقية إنما تكون بالإسلام. والموتى يخرجهم الله من قبورهم أحياء، ثم يعودون إليه يوم القيامة؛ ليُوَفَّوْا حسابهم وجزاءهم."},{"id":"826","jozz":"7","page":"132","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"3","aya_no":"37","aya_text":"وَقَالُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةٗ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ","aya_text_emlaey":"وقالوا لولا نـزل عليه آية من ربه قل إن الله قادر على أن ينـزل آية ولكن أكثرهم لا يعلمون","aya_tafseer":"[37] وقال المشركون -تعنتاً واستكباراً-: هلَّا أنزل الله علامة تدل على صدق محمد -صلى الله عليه وسلم- من نوع العلامات الخارقة، قل لهم -أيها الرسول-: إن الله قادر على أن ينزل عليهم آية، ولكن أكثرهم لا يعلمون أن إنزال الآيات إنما يكون وَفْق حكمته تعالى."},{"id":"827","jozz":"7","page":"132","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"3","line_end":"5","aya_no":"38","aya_text":"وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ وَلَا طَٰٓئِرٖ يَطِيرُ بِجَنَاحَيۡهِ إِلَّآ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ ثُمَّ إِلَىٰ رَبِّهِمۡ يُحۡشَرُونَ","aya_text_emlaey":"وما من دابة في الأرض ولا طائر يطير بجناحيه إلا أمم أمثالكم ما فرطنا في الكتاب من شيء ثم إلى ربهم يحشرون","aya_tafseer":"[38] ليس في الأرض حيوان يَدِبُّ على الأرض، أو طائر يطير في السماء بجناحيه إلا جماعات متجانسة الخلق مثلكم. ما تركنا في اللوح المحفوظ شيئاً إلا أثبتناه، ثم إنهم إلى ربهم يحشرون يوم القيامة، فيحاسِبُ الله كُلّاً بما عمل."},{"id":"828","jozz":"7","page":"132","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"7","aya_no":"39","aya_text":"وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا صُمّٞ وَبُكۡمٞ فِي ٱلظُّلُمَٰتِۗ مَن يَشَإِ ٱللَّهُ يُضۡلِلۡهُ وَمَن يَشَأۡ يَجۡعَلۡهُ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"والذين كذبوا بآياتنا صم وبكم في الظلمات من يشأ الله يضلله ومن يشأ يجعله على صراط مستقيم","aya_tafseer":"[39] والذين كذبوا بحجج الله تعالى صمٌّ لا يسمعون ما ينفعهم، بُكْمٌ لا يتكلمون بالحق، فهم حائرون في الظلمات، لم يختاروا طريقة الاستقامة. من يشأ الله إضلاله يضلله، ومن يشأ هدايته يجعله على صراط مستقيم."},{"id":"829","jozz":"7","page":"132","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"9","aya_no":"40","aya_text":"قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ أَوۡ أَتَتۡكُمُ ٱلسَّاعَةُ أَغَيۡرَ ٱللَّهِ تَدۡعُونَ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"قل أرأيتكم إن أتاكم عذاب الله أو أتتكم الساعة أغير الله تدعون إن كنتم صادقين","aya_tafseer":"[40] قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن جاءكم عذاب الله في الدنيا، أو جاءتكم الساعة التي تبعثون فيها: أغير الله تدعون هناك لكشف ما نزل بكم من البلاء، إن كنتم محقين في زعمكم أن آلهتكم التي تعبدونها من دون الله تنفع أو تضر؟"},{"id":"830","jozz":"7","page":"132","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"10","aya_no":"41","aya_text":"بَلۡ إِيَّاهُ تَدۡعُونَ فَيَكۡشِفُ مَا تَدۡعُونَ إِلَيۡهِ إِن شَآءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ","aya_text_emlaey":"بل إياه تدعون فيكشف ما تدعون إليه إن شاء وتنسون ما تشركون","aya_tafseer":"[41] بل تدعون -هناك- ربكم الذي خلقكم لا غيره، وتستغيثون به، فيفرِّجُ عنكم البلاء العظيم النازل بكم إن شاء؛ لأنه القادر على كل شيء، وتتركون حينئذ أصنامكم وأوثانكم وأولياءكم."},{"id":"831","jozz":"7","page":"132","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"12","aya_no":"42","aya_text":"وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَأَخَذۡنَٰهُم بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَتَضَرَّعُونَ","aya_text_emlaey":"ولقد أرسلنا إلى أمم من قبلك فأخذناهم بالبأساء والضراء لعلهم يتضرعون","aya_tafseer":"[42] ولقد بعثنا -أيها الرسول- إلى جماعات من الناس من قبلك رسلاً يدعونهم إلى الله تعالى، فكذَّبوهم، فابتليناهم في أموالهم بشدة الفقر وضيق المعيشة، وابتليناهم في أجسامهم بالأمراض والآلام؛ رجاء أن يتذللوا لربهم، ويخضعوا له وحده بالعبادة."},{"id":"832","jozz":"7","page":"132","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"13","aya_no":"43","aya_text":"فَلَوۡلَآ إِذۡ جَآءَهُم بَأۡسُنَا تَضَرَّعُواْ وَلَٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"فلولا إذ جاءهم بأسنا تضرعوا ولكن قست قلوبهم وزين لهم الشيطان ما كانوا يعملون","aya_tafseer":"[43] فهلَّا إذ جاء هذه الأممَ المكذبةَ بلاؤنا تذللوا لنا، ولكن قست قلوبهم، وزيَّن لهم الشيطان ما كانوا يعملون من المعاصي، ويأتون من الشرك."},{"id":"833","jozz":"7","page":"132","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"15","aya_no":"44","aya_text":"فَلَمَّا نَسُواْ مَا ذُكِّرُواْ بِهِۦ فَتَحۡنَا عَلَيۡهِمۡ أَبۡوَٰبَ كُلِّ شَيۡءٍ حَتَّىٰٓ إِذَا فَرِحُواْ بِمَآ أُوتُوٓاْ أَخَذۡنَٰهُم بَغۡتَةٗ فَإِذَا هُم مُّبۡلِسُونَ","aya_text_emlaey":"فلما نسوا ما ذكروا به فتحنا عليهم أبواب كل شيء حتى إذا فرحوا بما أوتوا أخذناهم بغتة فإذا هم مبلسون","aya_tafseer":"[44] فلما تركوا العمل بأوامر الله تعالى معرضين عنها، فتحنا عليهم أبواب كل شيء من الرزق فأبدلناهم بالبأساء رخاءً في العيش، وبالضراء صحة في الأجسام؛ استدراجاً مِنَّا لهم، حتى إذا بَطِروا، وأُعجبوا بما أعطيناهم من الخير والنعمة أخذناهم بالعذاب فجأة، فإذا هم آيسون منقطعون من كل خير."},{"id":"834","jozz":"7","page":"133","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"1","aya_no":"45","aya_text":"فَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِينَ ظَلَمُواْۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"فقطع دابر القوم الذين ظلموا والحمد لله رب العالمين","aya_tafseer":"[45] فاستؤصل هؤلاء القوم وأُهلكوا؛ إذ كفروا بالله وكذَّبوا رسله، فلم يبق منهم أحد. والشكر والثناء لله تعالى -خالق كل شيء ومالكه- على نصرة أوليائه وهلاك أعدائه."},{"id":"835","jozz":"7","page":"133","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"4","aya_no":"46","aya_text":"قُلۡ أَرَءَيۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِهِۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ ثُمَّ هُمۡ يَصۡدِفُونَ","aya_text_emlaey":"قل أرأيتم إن أخذ الله سمعكم وأبصاركم وختم على قلوبكم من إله غير الله يأتيكم به انظر كيف نصرف الآيات ثم هم يصدفون","aya_tafseer":"[46] قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن أذهب الله سمعكم فأصمَّكم، وذهب بأبصاركم فأعماكم، وطبع على قلوبكم فأصبحتم لا تفقهون قولاً، أيُّ إله غير الله -جل وعلا- يقدر على ردِّ ذلك لكم؟! انظر -أيها الرسول- كيف ننوِّع لهم الحجج، ثم هم بعد ذلك يعرضون عن التذكر والاعتبار؟"},{"id":"836","jozz":"7","page":"133","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"5","aya_no":"47","aya_text":"قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ بَغۡتَةً أَوۡ جَهۡرَةً هَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلظَّٰلِمُونَ","aya_text_emlaey":"قل أرأيتكم إن أتاكم عذاب الله بغتة أو جهرة هل يهلك إلا القوم الظالمون","aya_tafseer":"[47] قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن نزل بكم عقاب الله فجأة وأنتم لا تشعرون به، أو ظاهراً عِياناً وأنتم تنظرون إليه: هل يُهْلك إلا القوم الظالمون الذين تجاوزوا الحد، بصرفهم العبادة لغير الله تعالى وبتكذيبهم رسله؟"},{"id":"837","jozz":"7","page":"133","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"7","aya_no":"48","aya_text":"وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۖ فَمَنۡ ءَامَنَ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","aya_text_emlaey":"وما نرسل المرسلين إلا مبشرين ومنذرين فمن آمن وأصلح فلا خوف عليهم ولا هم يحزنون","aya_tafseer":"[48] وما نرسل رسلنا إلا مبشرين أهل طاعتنا بالنعيم المقيم، ومنذرين أهل المعصية بالعذاب الأليم، فمن آمن وصَدَّق الرسل وعمل صالحاً فأولئك لا يخافون عند لقاء ربهم، ولا يحزنون على شيء فاتهم من حظوظ الدنيا."},{"id":"838","jozz":"7","page":"133","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"8","aya_no":"49","aya_text":"وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلۡعَذَابُ بِمَا كَانُواْ يَفۡسُقُونَ","aya_text_emlaey":"والذين كذبوا بآياتنا يمسهم العذاب بما كانوا يفسقون","aya_tafseer":"[49] والذين كذَّبوا بآياتنا من القرآن والمعجزات فأولئك يصيبهم العذاب يوم القيامة؛ بسبب كفرهم وخروجهم عن طاعة الله تعالى."},{"id":"839","jozz":"7","page":"133","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"8","line_end":"11","aya_no":"50","aya_text":"قُل لَّآ أَقُولُ لَكُمۡ عِندِي خَزَآئِنُ ٱللَّهِ وَلَآ أَعۡلَمُ ٱلۡغَيۡبَ وَلَآ أَقُولُ لَكُمۡ إِنِّي مَلَكٌۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُۚ أَفَلَا تَتَفَكَّرُونَ","aya_text_emlaey":"قل لا أقول لكم عندي خزائن الله ولا أعلم الغيب ولا أقول لكم إني ملك إن أتبع إلا ما يوحى إلي قل هل يستوي الأعمى والبصير أفلا تتفكرون","aya_tafseer":"[50] قل -أيها الرسول- لهؤلاء المشركين: إني لا أدَّعي أني أملك خزائن السموات والأرض، فأتصرف فيها، ولا أدَّعي أني أعلم الغيب، ولا أدَّعي أني ملَك، وإنما أنا رسول من عند الله، أتبع ما يوحى إليَّ، وأبلِّغ وحيه إلى الناس، قل -أيها الرسول- لهؤلاء المشركين: هل يستوي الكافر الذي عَمِي عن آيات الله تعالى فلم يؤمن بها، والمؤمنُ الذي أبصر آيات الله فآمن بها؟ أفلا تتفكرون في آيات الله؛ لتبصروا الحق فتؤمنوا به؟"},{"id":"840","jozz":"7","page":"133","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"11","line_end":"12","aya_no":"51","aya_text":"وَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ لَيۡسَ لَهُم مِّن دُونِهِۦ وَلِيّٞ وَلَا شَفِيعٞ لَّعَلَّهُمۡ يَتَّقُونَ","aya_text_emlaey":"وأنذر به الذين يخافون أن يحشروا إلى ربهم ليس لهم من دونه ولي ولا شفيع لعلهم يتقون","aya_tafseer":"[51] وخَوِّف -أيها الرسول- بالقرآن الذين يعلمون أنهم يُحشرون إلى ربهم، فهم مصدِّقون بوعد الله ووعيده، ليس لهم غير الله وليٌّ ينصرهم، ولا شفيع يشفع لهم عنده تعالى، فيخلصهم من عذابه؛ لعلهم يتقون الله تعالى بفعل الأوامر واجتناب النواهي."},{"id":"841","jozz":"7","page":"133","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"15","aya_no":"52","aya_text":"وَلَا تَطۡرُدِ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ مَا عَلَيۡكَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَمَا مِنۡ حِسَابِكَ عَلَيۡهِم مِّن شَيۡءٖ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"ولا تطرد الذين يدعون ربهم بالغداة والعشي يريدون وجهه ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء فتطردهم فتكون من الظالمين","aya_tafseer":"[52] ولا تُبْعِد -أيها النبي- عن مجالستك ضعفاء المسلمين الذين يعبدون ربهم أول النهار وآخره، يريدون بأعمالهم الصالحة وجه الله، ما عليك من حساب هؤلاء الفقراء من شيء، إنما حسابهم على الله، وليس عليهم شيء من حسابك، فإن أبعدتهم فإنك تكون من المتجاوزين حدود الله، الذين يضعون الشيء في غير موضعه."},{"id":"842","jozz":"7","page":"134","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"53","aya_text":"وَكَذَٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضٖ لِّيَقُولُوٓاْ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيۡهِم مِّنۢ بَيۡنِنَآۗ أَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّٰكِرِينَ","aya_text_emlaey":"وكذلك فتنا بعضهم ببعض ليقولوا أهؤلاء من الله عليهم من بيننا أليس الله بأعلم بالشاكرين","aya_tafseer":"[53] وكذلك ابتلى الله تعالى بعض عباده ببعض بتباين حظوظهم من الأرزاق والأخلاق، فجعل بعضَهم غنيّاً وبعضهم فقيراً، وبعضهم قويّاً وبعضهم ضعيفاً، فأحوج بعضهم إلى بعض اختباراً منه لهم بذلك؛ ليقول الكافرون الأغنياء: أهؤلاء الضعفاء مَنَّ الله عليهم بالهداية إلى الإسلام مِن بيننا؟ أليس الله تعالى بأعلم بمن يشكرون نعمته، فيوفقهم إلى الهداية لدينه؟"},{"id":"843","jozz":"7","page":"134","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"5","aya_no":"54","aya_text":"وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤۡمِنُونَ بِـَٔايَٰتِنَا فَقُلۡ سَلَٰمٌ عَلَيۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوٓءَۢا بِجَهَٰلَةٖ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"وإذا جاءك الذين يؤمنون بآياتنا فقل سلام عليكم كتب ربكم على نفسه الرحمة أنه من عمل منكم سوءا بجهالة ثم تاب من بعده وأصلح فأنه غفور رحيم","aya_tafseer":"[54] وإذا جاءك -أيها النبي- الذين صَدَّقوا بآيات الله الشاهدة على صدقك من القرآن وغيره مستفتين عن التوبة من ذنوبهم السابقة، فأكرِمْهم بردِّ السلام عليهم، وبَشِّرهم برحمة الله الواسعة؛ فإنه جلَّ وعلا قد كتب على نفسه الرحمة بعباده تفضلاً أنه من اقترف ذنباً بجهالة منه لعاقبتها وإيجابها لسخط الله -فكل عاص لله -مخطئاً أو متعمداً- فهو جاهل بهذا الاعتبار وإن كان عالماً بالتحريم- ثم تاب من بعده وداوم على العمل الصالح، فأنَّه تعالى يغفر ذنبه، فهو غفور لعباده التائبين، رحيم بهم."},{"id":"844","jozz":"7","page":"134","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"6","aya_no":"55","aya_text":"وَكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ وَلِتَسۡتَبِينَ سَبِيلُ ٱلۡمُجۡرِمِينَ","aya_text_emlaey":"وكذلك نفصل الآيات ولتستبين سبيل المجرمين","aya_tafseer":"[55] ومثل هذا البيان الذي بيَّنَّاه لك -أيها الرسول- نبيِّن الحجج الواضحة على كل حق ينكره أهل الباطل؛ ليتبين الحق، وليظهر طريق أهل الباطل المخالفين للرسل."},{"id":"845","jozz":"7","page":"134","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"8","aya_no":"56","aya_text":"قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّآ أَتَّبِعُ أَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذٗا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ","aya_text_emlaey":"قل إني نهيت أن أعبد الذين تدعون من دون الله قل لا أتبع أهواءكم قد ضللت إذا وما أنا من المهتدين","aya_tafseer":"[56] قل -أيها الرسول- لهؤلاء المشركين: إن الله عز وجل نهاني أن أعبد الأوثان التي تعبدونها من دونه، وقل لهم: لا أتبع أهواءكم، قد ضللت عن الصراط المستقيم إن اتبعت أهواءَكم، وما أنا من المهتدين."},{"id":"846","jozz":"7","page":"134","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"11","aya_no":"57","aya_text":"قُلۡ إِنِّي عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَكَذَّبۡتُم بِهِۦۚ مَا عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦٓۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ يَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَيۡرُ ٱلۡفَٰصِلِينَ","aya_text_emlaey":"قل إني على بينة من ربي وكذبتم به ما عندي ما تستعجلون به إن الحكم إلا لله يقص الحق وهو خير الفاصلين","aya_tafseer":"[57] قل -أيها الرسول لهؤلاء المشركين-: إني على بصيرة واضحة من شريعة الله التي أوحاها إليَّ، وذلك بإفراده وحده بالعبادة، وقد كذَّبتم بهذا، وليس في قدرتي إنزال العذاب الذي تستعجلون به، وما الحكم في تأخر ذلك إلا إلى الله تعالى، يبيِّن الحقَّ بياناً واضحاً، وهو خير مَن يفصل بين الحق والباطل بقضائه وحكمه."},{"id":"847","jozz":"7","page":"134","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"11","line_end":"12","aya_no":"58","aya_text":"قُل لَّوۡ أَنَّ عِندِي مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِيَ ٱلۡأَمۡرُ بَيۡنِي وَبَيۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّٰلِمِينَ","aya_text_emlaey":"قل لو أن عندي ما تستعجلون به لقضي الأمر بيني وبينكم والله أعلم بالظالمين","aya_tafseer":"[58] قل -أيها الرسول-: لو أنني أملك إنزال العذاب الذي تستعجلونه لأنزلته بكم، وقضي الأمر بيني وبينكم، ولكن ذلك إلى الله تعالى، وهو أعلم بالظالمين الذين تجاوزوا حدَّهم فأشركوا معه غيره."},{"id":"848","jozz":"7","page":"134","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"15","aya_no":"59","aya_text":"۞ وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّةٖ فِي ظُلُمَٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبٖ وَلَا يَابِسٍ إِلَّا فِي كِتَٰبٖ مُّبِينٖ","aya_text_emlaey":"وعنده مفاتح الغيب لا يعلمها إلا هو ويعلم ما في البر والبحر وما تسقط من ورقة إلا يعلمها ولا حبة في ظلمات الأرض ولا رطب ولا يابس إلا في كتاب مبين","aya_tafseer":"[59] وعند الله -جل وعلا -مفاتح الغيب، أي: خزائن الغيب، لا يعلمها إلَّا هو، ومنها: علم الساعة، ونزول الغيث، وما في الأرحام، والكسب في المستقبل، ومكان موت الإنسان، ويعلمُ كلَّ ما في البر والبحر، وما تسقط من ورقة من نبتة إلا يعلمها، فكل حبة في خفايا الأرض، وكل رطب ويابس، مثبت في كتاب واضح لا لَبْس فيه، وهو اللوح المحفوظ."},{"id":"849","jozz":"7","page":"135","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"3","aya_no":"60","aya_text":"وَهُوَ ٱلَّذِي يَتَوَفَّىٰكُم بِٱلَّيۡلِ وَيَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ يَبۡعَثُكُمۡ فِيهِ لِيُقۡضَىٰٓ أَجَلٞ مُّسَمّٗىۖ ثُمَّ إِلَيۡهِ مَرۡجِعُكُمۡ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","aya_text_emlaey":"وهو الذي يتوفاكم بالليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضى أجل مسمى ثم إليه مرجعكم ثم ينبئكم بما كنتم تعملون","aya_tafseer":"[60] وهو سبحانه الذي يقبض أرواحكم بالليل بما يشبه قبضها عند الموت، ويعلم ما اكتسبتم في النهار من الأعمال، ثم يعيد أرواحكم إلى أجسامكم باليقظة من النوم نهاراً بما يشبه الإحياء بعد الموت؛ لتُقضى آجالكم المحددة في الدنيا، ثم إلى الله تعالى معادكم بعد بعثكم من قبوركم أحياءً، ثم يخبركم بما كنتم تعملون في حياتكم الدنيا، ثم يجازيكم بذلك."},{"id":"850","jozz":"7","page":"135","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"3","line_end":"5","aya_no":"61","aya_text":"وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَيُرۡسِلُ عَلَيۡكُمۡ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا يُفَرِّطُونَ","aya_text_emlaey":"وهو القاهر فوق عباده ويرسل عليكم حفظة حتى إذا جاء أحدكم الموت توفته رسلنا وهم لا يفرطون","aya_tafseer":"[61] والله تعالى هو القاهر فوق عباده، فوقية مطلقة من كل وجه، تليق بجلاله سبحانه وتعالى. كل شيء خاضع لجلاله وعظمته، ويرسل على عباده ملائكة، يحفظون أعمالهم ويُحْصونها، حتى إذا نزل الموت بأحدهم قبض روحَه ملَكُ الموت وأعوانه، وهم لا يضيعون ما أُمروا به."},{"id":"851","jozz":"7","page":"135","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"6","aya_no":"62","aya_text":"ثُمَّ رُدُّوٓاْ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۚ أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَٰسِبِينَ","aya_text_emlaey":"ثم ردوا إلى الله مولاهم الحق ألا له الحكم وهو أسرع الحاسبين","aya_tafseer":"[62] ثم أعيد هؤلاء المتوفَّوْن إلى الله تعالى مولاهم الحق. ألا له القضاء والفصل يوم القيامة بين عباده، وهو أسرع الحاسبين."},{"id":"852","jozz":"7","page":"135","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"8","aya_no":"63","aya_text":"قُلۡ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعٗا وَخُفۡيَةٗ لَّئِنۡ أَنجَىٰنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ","aya_text_emlaey":"قل من ينجيكم من ظلمات البر والبحر تدعونه تضرعا وخفية لئن أنجانا من هذه لنكونن من الشاكرين","aya_tafseer":"[63] قل -أيها الرسول- لهؤلاء المشركين: من ينقذكم مِن مخاوف ظلمات البر والبحر؟ أليس هو الله تعالى الذي تدعونه في الشدائد متذللين جهراً وسرّاً؟ تقولون: لئن أنجانا ربُّنا من هذه المخاوف لنكونن من الشاكرين بعبادته عز وجل وحده لا شريك له."},{"id":"853","jozz":"7","page":"135","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"8","line_end":"9","aya_no":"64","aya_text":"قُلِ ٱللَّهُ يُنَجِّيكُم مِّنۡهَا وَمِن كُلِّ كَرۡبٖ ثُمَّ أَنتُمۡ تُشۡرِكُونَ","aya_text_emlaey":"قل الله ينجيكم منها ومن كل كرب ثم أنتم تشركون","aya_tafseer":"[64] قل لهم -أيها الرسول-: الله وحده هو الذي ينقذكم من هذه المخاوف ومن كل شدة، ثم أنتم بعد ذلك تشركون معه في العبادة غيره."},{"id":"854","jozz":"7","page":"135","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"11","aya_no":"65","aya_text":"قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابٗا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ","aya_text_emlaey":"قل هو القادر على أن يبعث عليكم عذابا من فوقكم أو من تحت أرجلكم أو يلبسكم شيعا ويذيق بعضكم بأس بعض انظر كيف نصرف الآيات لعلهم يفقهون","aya_tafseer":"[65] قل -أيها الرسول-: الله عز وجل هو القادر وحده على أن يرسل عليكم عذاباً مِن فوقكم كالرَّجْم أو الطوفان، وما أشبه ذلك، أو من تحت أرجلكم كالزلازل والخسف، أو يخلط أمركم عليكم فتكونوا فرقاً متناحرة يقتل بعضكم بعضاً. انظر -أيها الرسول- كيف نُنوِّع حججنا الواضحات لهؤلاء المشركين لعلهم يفهمون فيعتبروا؟"},{"id":"855","jozz":"7","page":"135","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"11","line_end":"12","aya_no":"66","aya_text":"وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَيۡكُم بِوَكِيلٖ","aya_text_emlaey":"وكذب به قومك وهو الحق قل لست عليكم بوكيل","aya_tafseer":"[66] وكذَّب بهذا القرآن الكفارُ من قومك أيها الرسول، وهو الكتاب الصادق في كل ما جاء به. قل لهم: لست عليكم بحفيظ ولا رقيب، وإنما أنا رسول الله أُبلغكم ما أُرسلت به إليكم."},{"id":"856","jozz":"7","page":"135","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"13","aya_no":"67","aya_text":"لِّكُلِّ نَبَإٖ مُّسۡتَقَرّٞۚ وَسَوۡفَ تَعۡلَمُونَ","aya_text_emlaey":"لكل نبإ مستقر وسوف تعلمون","aya_tafseer":"[67] لكل خبر قرار يستقر عنده، ونهاية ينتهي إليها، فيتبيَّن الحق من الباطل، وسوف تعلمون -أيها الكفار- عاقبة أمركم عند حلول عذاب الله بكم."},{"id":"857","jozz":"7","page":"135","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"15","aya_no":"68","aya_text":"وَإِذَا رَأَيۡتَ ٱلَّذِينَ يَخُوضُونَ فِيٓ ءَايَٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيۡطَٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","aya_text_emlaey":"وإذا رأيت الذين يخوضون في آياتنا فأعرض عنهم حتى يخوضوا في حديث غيره وإما ينسينك الشيطان فلا تقعد بعد الذكرى مع القوم الظالمين","aya_tafseer":"[68] وإذا رأيت -أيها الرسول- المشركين الذين يتكلمون في آيات القرآن بالباطل والاستهزاء، فابتعد عنهم حتى يأخذوا في حديث آخر، وإن أنساك الشيطان هذا الأمر فلا تقعد بعد تذكرك مع القوم المعتدين، الذين تكلموا في آيات الله بالباطل."},{"id":"858","jozz":"7","page":"136","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"69","aya_text":"وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَيۡءٖ وَلَٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ يَتَّقُونَ","aya_text_emlaey":"وما على الذين يتقون من حسابهم من شيء ولكن ذكرى لعلهم يتقون","aya_tafseer":"[69] وما على المؤمنين الذين يخافون الله تعالى، فيطيعون أوامره، ويجتنبون نواهيه من حساب الله للخائضين المستهزئين بآيات الله من شيء، ولكن عليهم أن يعظوهم ليمسكوا عن ذلك الكلام الباطل، لعلهم يتقون الله تعالى."},{"id":"859","jozz":"7","page":"136","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"7","aya_no":"70","aya_text":"وَذَرِ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَعِبٗا وَلَهۡوٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ وَذَكِّرۡ بِهِۦٓ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِيّٞ وَلَا شَفِيعٞ وَإِن تَعۡدِلۡ كُلَّ عَدۡلٖ لَّا يُؤۡخَذۡ مِنۡهَآۗ أُوْلَٰٓئِكَ ٱلَّذِينَ أُبۡسِلُواْ بِمَا كَسَبُواْۖ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ","aya_text_emlaey":"وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحياة الدنيا وذكر به أن تبسل نفس بما كسبت ليس لها من دون الله ولي ولا شفيع وإن تعدل كل عدل لا يؤخذ منها أولئك الذين أبسلوا بما كسبوا لهم شراب من حميم وعذاب أليم بما كانوا يكفرون","aya_tafseer":"[70] واترك -أيها الرسول- هؤلاء المشركين الذين جعلوا دين الإسلام لعباً ولهواً؛ مستهزئين بآيات الله تعالى، وغَرَّتهم الحياة الدنيا بزينتها، وذكِّر بالقرآن هؤلاء المشركين وغيرَهم؛ كي لا تُرْتَهَنَ نفس بذنوبها وكفرها بربها، ليس لها غير الله ناصر ينصرها، فينقذها من عذابه، ولا شافع يشفع لها عنده، وإن تَفْتَدِ بأي فداء لا يُقبَل منها. أولئك الذين ارتُهِنوا بذنوبهم، لهم في النار شراب شديد الحرارة وعذاب موجع؛ بسبب كفرهم بالله تعالى، ورسوله محمَّد -صلى الله عليه وسلم-، وبدين الإسلام."},{"id":"860","jozz":"7","page":"136","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"11","aya_no":"71","aya_text":"قُلۡ أَنَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِي ٱسۡتَهۡوَتۡهُ ٱلشَّيَٰطِينُ فِي ٱلۡأَرۡضِ حَيۡرَانَ لَهُۥٓ أَصۡحَٰبٞ يَدۡعُونَهُۥٓ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"قل أندعوا من دون الله ما لا ينفعنا ولا يضرنا ونرد على أعقابنا بعد إذ هدانا الله كالذي استهوته الشياطين في الأرض حيران له أصحاب يدعونه إلى الهدى ائتنا قل إن هدى الله هو الهدى وأمرنا لنسلم لرب العالمين","aya_tafseer":"[71] قل -أيها الرسول- لهؤلاء المشركين: أنعبد من دون الله تعالى أوثاناً لا تنفع ولا تضر؟ ونرجع إلى الكفر بعد هداية الله تعالى لنا إلى الإسلام، فنشبه -في رجوعنا إلى الكفر- مَن فسد عقله باستهواء الشياطين له، فَضَلَّ في الأرض، وله رُفْقَةٌ عقلاء مؤمنون يدعونه إلى الطريق الصحيح الذي هم عليه فيأبى. قل -أيها الرسول- لهؤلاء المشركين: إنَّ هدى الله الذي بعثني به هو الهدى الحق، وأُمرنا جميعاً لنسلم لله تعالى رب العالمين بعبادته وحده لا شريك له، فهو رب كل شيء ومالكه."},{"id":"861","jozz":"7","page":"136","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"11","line_end":"12","aya_no":"72","aya_text":"وَأَنۡ أَقِيمُواْ ٱلصَّلَوٰةَ وَٱتَّقُوهُۚ وَهُوَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ","aya_text_emlaey":"وأن أقيموا الصلاة واتقوه وهو الذي إليه تحشرون","aya_tafseer":"[72] وكذلك أُمرنا بأن نقيم الصلاة كاملة، وأن نخشاه بفعل أوامره واجتناب نواهيه. وهو -جل وعلا- الذي إليه تُحْشَرُ جميع الخلائق يوم القيامة."},{"id":"862","jozz":"7","page":"136","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"15","aya_no":"73","aya_text":"وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَيَوۡمَ يَقُولُ كُن فَيَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ","aya_text_emlaey":"وهو الذي خلق السموات والأرض بالحق ويوم يقول كن فيكون قوله الحق وله الملك يوم ينفخ في الصور عالم الغيب والشهادة وهو الحكيم الخبير","aya_tafseer":"[73] والله سبحانه هو الذي خلق السموات والأرض بالحق، واذكر -أيها الرسول- يوم القيامة إذ يقول الله: «كن»، فيكون عن أمره كلمح البصر أو هو أقرب، قوله هو الحق الكامل، وله الملك سبحانه وحده، يوم ينفخ المَلَك في «القَرْن» النفخة الثانية التي تكون بها عودة الأرواح إلى الأجسام. وهو سبحانه الذي يعلم ما غاب عن حواسكم -أيها الناس- وما تشاهدونه، وهو الحكيم الذي يضع الأمور في مواضعها، الخبير بأمور خلقه. والله تعالى هو الذي يختص بهذه الأمور وغيرها بدءاً ونهاية، نشأة ومصيراً، وهو وحده الذي يجب على العباد الانقياد لشرعه، والتسليم لحكمه، والتطلع إلى رضوانه ومغفرته."},{"id":"863","jozz":"7","page":"137","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"74","aya_text":"۞ وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلٖ مُّبِينٖ","aya_text_emlaey":"وإذ قال إبراهيم لأبيه آزر أتتخذ أصناما آلهة إني أراك وقومك في ضلال مبين","aya_tafseer":"[74] واذكر -أيها الرسول- مُحاجَّة إبراهيم عليه السلام لأبيه آزرَ، إذ قال له: أتجعل من الأصنام آلهة تعبدها من دون الله تعالى؟ إني أراك وقومك في ضلال بيِّن عن طريق الحق."},{"id":"864","jozz":"7","page":"137","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"3","aya_no":"75","aya_text":"وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ","aya_text_emlaey":"وكذلك نري إبراهيم ملكوت السموات والأرض وليكون من الموقنين","aya_tafseer":"[75] وكما هدينا إبراهيم عليه السلام إلى الحق في أمر العبادة نُريه ما تحتوي عليه السموات والأرض مِن ملك عظيم، وقدرة باهرة؛ ليكون من الراسخين في الإيمان."},{"id":"865","jozz":"7","page":"137","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"5","aya_no":"76","aya_text":"فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ","aya_text_emlaey":"فلما جن عليه الليل رأى كوكبا قال هذا ربي فلما أفل قال لا أحب الآفلين","aya_tafseer":"[76] فلما أظلم على إبراهيم -عليه السلام- الليل وغطَّاه ناظر قومه؛ ليثبت لهم أن دينهم باطل، وكانوا يعبدون النجوم. رأى إبراهيم عليه السلام كوكباً، فقال -مستدرجاً قومه لإلزامهم بالتوحيد-: هذا ربي، فلما غاب الكوكب، قال: لا أحب الآلهة التي تغيب."},{"id":"866","jozz":"7","page":"137","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"7","aya_no":"77","aya_text":"فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغٗا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ","aya_text_emlaey":"فلما رأى القمر بازغا قال هذا ربي فلما أفل قال لئن لم يهدني ربي لأكونن من القوم الضالين","aya_tafseer":"[77] فلما رأى إبراهيم القمر طالعاً قال لقومه -على سبيل استدراج الخصم-: هذا ربي، فلما غاب، قال: -مفتقراً إلى هداية ربه- لئن لم يوفقني ربي إلى الصواب في توحيده، لأكونن من القوم الضالين عن سواء السبيل بعبادة غير الله تعالى."},{"id":"867","jozz":"7","page":"137","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"8","aya_no":"78","aya_text":"فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةٗ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ","aya_text_emlaey":"فلما رأى الشمس بازغة قال هذا ربي هذا أكبر فلما أفلت قال ياقوم إني بريء مما تشركون","aya_tafseer":"[78] فلما رأى الشمس طالعة قال لقومه: هذا ربي، هذا أكبر من الكوكب والقمر، فلما غابت، قال لقومه: إني بريء مما تشركون من عبادة الأوثان والنجوم والأصنام التي تعبدونها من دون الله تعالى."},{"id":"868","jozz":"7","page":"137","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"10","aya_no":"79","aya_text":"إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"إني وجهت وجهي للذي فطر السموات والأرض حنيفا وما أنا من المشركين","aya_tafseer":"[79] إني توجَّهْتُ بوجهي في العبادة لله عز وجل وحده، فهو الذي خلق السموات والأرض، مائلاً عن الشرك إلى التوحيد، وما أنا من المشركين مع الله غيره."},{"id":"869","jozz":"7","page":"137","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"13","aya_no":"80","aya_text":"وَحَآجَّهُۥ قَوۡمُهُۥۚ قَالَ أَتُحَٰٓجُّوٓنِّي فِي ٱللَّهِ وَقَدۡ هَدَىٰنِۚ وَلَآ أَخَافُ مَا تُشۡرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّي شَيۡـٔٗاۚ وَسِعَ رَبِّي كُلَّ شَيۡءٍ عِلۡمًاۚ أَفَلَا تَتَذَكَّرُونَ","aya_text_emlaey":"وحاجه قومه قال أتحاجوني في الله وقد هدان ولا أخاف ما تشركون به إلا أن يشاء ربي شيئا وسع ربي كل شيء علما أفلا تتذكرون","aya_tafseer":"[80] وجادله قومه في توحيد الله تعالى قال: أتجادلونني في توحيدي لله بالعبادة، وقد وفقني إلى معرفة وحدانيته، فإن كنتم تخوفونني بآلهتكم أن توقع بي ضرراً فإنني لا أرهبها فلن تضرني، إلا أن يشاء ربي شيئاً. وسع ربي كل شيء علماً. أفلا تتذكرون فتعلموا أنه وحده المعبود المستحق للعبودية؟"},{"id":"870","jozz":"7","page":"137","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"15","aya_no":"81","aya_text":"وَكَيۡفَ أَخَافُ مَآ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ عَلَيۡكُمۡ سُلۡطَٰنٗاۚ فَأَيُّ ٱلۡفَرِيقَيۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"وكيف أخاف ما أشركتم ولا تخافون أنكم أشركتم بالله ما لم ينـزل به عليكم سلطانا فأي الفريقين أحق بالأمن إن كنتم تعلمون","aya_tafseer":"[81] وكيف أخاف أوثانكم وأنتم لا تخافون ربي الذي خلقكم، وخلق أوثانكم التي أشركتموها معه في العبادة، من غير حجة لكم على ذلك؟ فأي الفريقين: فريق المشركين وفريق الموحدين أحق بالطمأنينة والسلامة والأمن من عذاب الله؟ إن كنتم تعلمون صدق ما أقول فأخبروني."},{"id":"871","jozz":"7","page":"138","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"82","aya_text":"ٱلَّذِينَ ءَامَنُواْ وَلَمۡ يَلۡبِسُوٓاْ إِيمَٰنَهُم بِظُلۡمٍ أُوْلَٰٓئِكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ","aya_text_emlaey":"الذين آمنوا ولم يلبسوا إيمانهم بظلم أولئك لهم الأمن وهم مهتدون","aya_tafseer":"[82] الذين صَدَّقوا الله ورسوله وعملوا بشرعه ولم يخلطوا إيمانهم بشرك، أولئك لهم الطمأنينة والسلامة، وهم الموفقون إلى طريق الحق."},{"id":"872","jozz":"7","page":"138","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"3","aya_no":"83","aya_text":"وَتِلۡكَ حُجَّتُنَآ ءَاتَيۡنَٰهَآ إِبۡرَٰهِيمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ","aya_text_emlaey":"وتلك حجتنا آتيناها إبراهيم على قومه نرفع درجات من نشاء إن ربك حكيم عليم","aya_tafseer":"[83] وتلك الحجة التي حاجَّ بها إبراهيمُ - عليه السلام - قومَه هي حجتنا التي وفقناه إليها حتى انقطعت حجتهم. نرفع مَن نشاء مِن عبادنا مراتب في الدنيا والآخرة. إن ربك حكيم في تدبير خلقه، عليم بهم."},{"id":"873","jozz":"7","page":"138","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"6","aya_no":"84","aya_text":"وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۚ كُلًّا هَدَيۡنَاۚ وَنُوحًا هَدَيۡنَا مِن قَبۡلُۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيۡمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"ووهبنا له إسحاق ويعقوب كلا هدينا ونوحا هدينا من قبل ومن ذريته داود وسليمان وأيوب ويوسف وموسى وهارون وكذلك نجزي المحسنين","aya_tafseer":"[84] ومننَّا على إبراهيم - عليه السلام - بأن رزقناه إسحاق ابناً ويعقوب حفيداً، ووفَّقنا كُلّاً منهما لسبيل الرشاد، وكذلك وفَّقنا للحق نوحاً -من قبل إبراهيم وإسحاق ويعقوب- وكذلك وفَّقنا للحق من ذرية نوحٍ داودَ وسليمان وأيوب ويوسف وموسى وهارون عليهم السلام، وكما جزينا هؤلاء الأنبياء بإحسانهم نجزي كل محسن."},{"id":"874","jozz":"7","page":"138","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"7","aya_no":"85","aya_text":"وَزَكَرِيَّا وَيَحۡيَىٰ وَعِيسَىٰ وَإِلۡيَاسَۖ كُلّٞ مِّنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"وزكريا ويحيى وعيسى وإلياس كل من الصالحين","aya_tafseer":"[85] وكذلك هدينا زكريا ويحيى وعيسى وإلياس، وكل هؤلاء الأنبياء عليهم السلام من الصالحين."},{"id":"875","jozz":"7","page":"138","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"8","line_end":"9","aya_no":"86","aya_text":"وَإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَيُونُسَ وَلُوطٗاۚ وَكُلّٗا فَضَّلۡنَا عَلَى ٱلۡعَٰلَمِينَ","aya_text_emlaey":"وإسماعيل واليسع ويونس ولوطا وكلا فضلنا على العالمين","aya_tafseer":"[86] وهدينا كذلك إسماعيل واليسع ويونس ولوطاً، وكل هؤلاء الرسل فضَّلناهم على أهل زمانهم."},{"id":"876","jozz":"7","page":"138","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"10","aya_no":"87","aya_text":"وَمِنۡ ءَابَآئِهِمۡ وَذُرِّيَّٰتِهِمۡ وَإِخۡوَٰنِهِمۡۖ وَٱجۡتَبَيۡنَٰهُمۡ وَهَدَيۡنَٰهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"ومن آبائهم وذرياتهم وإخوانهم واجتبيناهم وهديناهم إلى صراط مستقيم","aya_tafseer":"[87] وكذلك وفَّقنا للحق مَن شئنا هدايته من آباء هؤلاء وذرياتهم وإخوانهم، واخترناهم لديننا وإبلاغ رسالتنا إلى مَن أرسلناهم إليهم، وأرشدناهم إلى طريق صحيح، لا عوج فيه، وهو توحيد الله تعالى وتنزيهه عن الشرك."},{"id":"877","jozz":"7","page":"138","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"12","aya_no":"88","aya_text":"ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَلَوۡ أَشۡرَكُواْ لَحَبِطَ عَنۡهُم مَّا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"ذلك هدى الله يهدي به من يشاء من عباده ولو أشركوا لحبط عنهم ما كانوا يعملون","aya_tafseer":"[88] ذلك الهدى هو توفيق الله، الذي يوفق به من يشاء من عباده. ولو أن هؤلاء الأنبياء أشركوا بالله -على سبيل الفرض والتقدير- لبطل عملهم؛ لأن الله تعالى لا يقبل مع الشرك عملاً."},{"id":"878","jozz":"7","page":"138","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"14","aya_no":"89","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن يَكۡفُرۡ بِهَا هَٰٓؤُلَآءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمٗا لَّيۡسُواْ بِهَا بِكَٰفِرِينَ","aya_text_emlaey":"أولئك الذين آتيناهم الكتاب والحكم والنبوة فإن يكفر بها هؤلاء فقد وكلنا بها قوما ليسوا بها بكافرين","aya_tafseer":"[89] أولئك الأنبياء الذين أنعمنا عليهم بالهداية والنبوة هم الذين آتيناهم الكتاب، كصحف إبراهيم وتوراة موسى وزبور داود وإنجيل عيسى، وآتيناهم فَهْمَ هذه الكتب، واخترناهم لإبلاغ وحينا، فإن يجحد -أيها الرسول- بآيات هذا القرآن الكفارُ من قومك، فقد وفَّقنا للإيمان بها والقيام بحقوقها قوماً آخرين -أي: المهاجرين والأنصار وأتباعهم إلى يوم القيامة- ليسوا بها بكافرين، بل مؤمنون بها، عاملون بما تدل عليه."},{"id":"879","jozz":"7","page":"138","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"14","line_end":"15","aya_no":"90","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَٰلَمِينَ","aya_text_emlaey":"أولئك الذين هدى الله فبهداهم اقتده قل لا أسألكم عليه أجرا إن هو إلا ذكرى للعالمين","aya_tafseer":"[90] أولئك الأنبياء المذكورون هم الذين وفقهم الله تعالى لدينه الحق، فاتَّبِعْ هداهم -أيها الرسول- واسلك سبيلهم. قل للمشركين: لا أطلب منكم على تبليغ الإسلام عوضاً من الدنيا، إنْ أجري إلا على الله، وما الإسلام إلا دعوة جميع الناس إلى الطريق المستقيم، وتذكيرٌ لكم ولكل مَن كان مثلكم، ممن هو مقيم على باطل، لعلكم تتذكرون به ما ينفعكم."},{"id":"880","jozz":"7","page":"139","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"5","aya_no":"91","aya_text":"وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓ إِذۡ قَالُواْ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٖ مِّن شَيۡءٖۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَٰبَ ٱلَّذِي جَآءَ بِهِۦ مُوسَىٰ نُورٗا وَهُدٗى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِيسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِيرٗاۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوٓاْ أَنتُمۡ وَلَآ ءَابَآؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِي خَوۡضِهِمۡ يَلۡعَبُونَ","aya_text_emlaey":"وما قدروا الله حق قدره إذ قالوا ما أنـزل الله على بشر من شيء قل من أنـزل الكتاب الذي جاء به موسى نورا وهدى للناس تجعلونه قراطيس تبدونها وتخفون كثيرا وعلمتم ما لم تعلموا أنتم ولا آباؤكم قل الله ثم ذرهم في خوضهم يلعبون","aya_tafseer":"[91] وما عَظَّم هؤلاء المشركون الله حق تعظيمه؛ إذ أنكروا أن يكون الله تعالى قد أنزل على أحد من البشر شيئاً من وحيه. قل لهم -أيها الرسول-: إذا كان الأمر كما تزعمون، فمن الذي أنزل الكتاب الذي جاء به موسى إلى قومه نوراً للناس وهداية لهم؟ ثم توجه الخطاب إلى اليهود زَجْراً لهم بقوله: تجعلون هذا الكتاب في قراطيس متفرقة، تظهرون بعضها، وتكتمون كثيراً منها، ومما كتموه الإخبار عن صفة محمد -صلى الله عليه وسلم- ونبوته، وعَلَّمكم الله معشر العرب بالقرآنِ -الذي أنزله عليكم، فيه خبر مَن قبلكم ومَن بعدكم، وما يكون بعد موتكم- ما لم تعلموه أنتم ولا آباؤكم؟ قل: الله هو الذي أنزله، ثم دع هؤلاء في حديثهم الباطل يخوضون ويلعبون."},{"id":"881","jozz":"7","page":"139","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"7","aya_no":"92","aya_text":"وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ مُّصَدِّقُ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَلِتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ يُؤۡمِنُونَ بِهِۦۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ","aya_text_emlaey":"وهذا كتاب أنـزلناه مبارك مصدق الذي بين يديه ولتنذر أم القرى ومن حولها والذين يؤمنون بالآخرة يؤمنون به وهم على صلاتهم يحافظون","aya_tafseer":"[92] وهذا القرآن كتاب أنزلناه إليك -أيها الرسول- عظيم النفع، يشهد على صدق ما تَقدَّمه من الكتب المنزَّلة وأنها من عند الله، أنزلناه لتخوِّف به من عذاب الله وبأسه أهل «مكة» ومَن حولها من أهل أقطار الأرض كلِّها. والذين يصدقون بالحياة الآخرة، يصدقون بأن القرآن كلام الله، ويحافظون على إقام الصلاة في أوقاتها."},{"id":"882","jozz":"7","page":"139","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"12","aya_no":"93","aya_text":"وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِيَ إِلَيَّ وَلَمۡ يُوحَ إِلَيۡهِ شَيۡءٞ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَآ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ ٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَيۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَايَٰتِهِۦ تَسۡتَكۡبِرُونَ","aya_text_emlaey":"ومن أظلم ممن افترى على الله كذبا أو قال أوحي إلي ولم يوح إليه شيء ومن قال سأنـزل مثل ما أنـزل الله ولو ترى إذ الظالمون في غمرات الموت والملائكة باسطو أيديهم أخرجوا أنفسكم اليوم تجزون عذاب الهون بما كنتم تقولون على الله غير الحق وكنتم عن آياته تستكبرون","aya_tafseer":"[93] ومَن أشدُّ ظلماً ممن اختلق على الله تعالى قولاً كذباً، فادَّعى أنه لم يبعث رسولاً من البشر، أو ادَّعى كذباً أن الله أوحى إليه ولم يُوْحِ إليه شيئاً، أو ادَّعى أنه قادر على أن يُنْزل مثل ما أنزل الله من القرآن؟ ولو أنك أبصرت -أيها الرسول- هؤلاء المتجاوزين الحدَّ وهم في أهوال الموت لرأيت أمراً هائلاً، والملائكةُ الذين يقبضون أرواحهم باسطو أيديهم بالعذاب قائلين لهم: أخرجوا أنفسكم، اليوم تهانون غاية الإهانة، كما كنتم تكذبون على الله، وتستكبرون عن اتباع آياته والانقياد لرسله."},{"id":"883","jozz":"7","page":"139","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"15","aya_no":"94","aya_text":"وَلَقَدۡ جِئۡتُمُونَا فُرَٰدَىٰ كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةٖ وَتَرَكۡتُم مَّا خَوَّلۡنَٰكُمۡ وَرَآءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمۡتُمۡ أَنَّهُمۡ فِيكُمۡ شُرَكَٰٓؤُاْۚ لَقَد تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ","aya_text_emlaey":"ولقد جئتمونا فرادى كما خلقناكم أول مرة وتركتم ما خولناكم وراء ظهوركم وما نرى معكم شفعاءكم الذين زعمتم أنهم فيكم شركاء لقد تقطع بينكم وضل عنكم ما كنتم تزعمون","aya_tafseer":"[94] ولقد جئتمونا للحساب والجزاء فرادى كما أوجدناكم في الدنيا أول مرة حفاة عراة، وتركتم وراء ظهوركم ما مكنَّاكم فيه مما تتباهَوْن به مِن أموال في الدنيا، وما نرى معكم في الآخرة أوثانكم التي كنتم تعتقدون أنها تشفع لكم، وتَدَّعون أنها شركاء مع الله في العبادة، لقد زال تَواصُلُكم الذي كان بينكم في الدنيا، وذهب عنكم ما كنتم تَدَّعون مِن أن آلهتكم شركاء لله في العبادة، وظهر أنكم الخاسرون لأنفسكم وأهليكم وأموالكم."},{"id":"884","jozz":"7","page":"140","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"95","aya_text":"۞ إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ","aya_text_emlaey":"إن الله فالق الحب والنوى يخرج الحي من الميت ومخرج الميت من الحي ذلكم الله فأنى تؤفكون","aya_tafseer":"[95] إن الله تعالى يشق الحب، فيخرج منه الزرع، ويشق النوى، فيخرج منه الشجر، يخرج الحي من الميت كالإنسان والحيوان مثلاً من النطفة، ويخرج الميت من الحي كالنطفة من الإنسان والحيوان؛ ذلكم الله أي: فاعل هذا هو الله وحده لا شريك له المستحق للعبادة، فكيف تُصْرَفون عن الحق إلى الباطل فتعبدون معه غيره ؟"},{"id":"885","jozz":"7","page":"140","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"4","aya_no":"96","aya_text":"فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّيۡلَ سَكَنٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ","aya_text_emlaey":"فالق الإصباح وجعل الليل سكنا والشمس والقمر حسبانا ذلك تقدير العزيز العليم","aya_tafseer":"[96] والله سبحانه وتعالى هو الذي شق ضياء الصباح من ظلام الليل، وجعل الليل مستقَراً، يسكن فيه مَن يتعب بالنهار فيأخذ نصيبه من الراحة، وجعل الشمس والقمر يجريان في فلكيهما بحساب متقن مقدَّر، لا يتغير ولا يضطرب، ذلك تقدير العزيز الذي عَزَّ سلطانه، العليم بمصالح خلقه وتدبير شؤونهم. والعزيز والعليم من أسماء الله الحسنى يدلان على كمال العزة والعلم."},{"id":"886","jozz":"7","page":"140","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"5","aya_no":"97","aya_text":"وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ","aya_text_emlaey":"وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر قد فصلنا الآيات لقوم يعلمون","aya_tafseer":"[97] والله سبحانه هو الذي جعل لكم - أيها الناس - النجوم علامات، تعرفون بها الطرق ليلاً إذا ضللتم؛ بسبب الظلمة الشديدة في البر والبحر، قد بيَّنَّا البراهين الواضحة؛ ليتدبرها منكم أولو العلم بالله وشرعه."},{"id":"887","jozz":"7","page":"140","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"7","aya_no":"98","aya_text":"وَهُوَ ٱلَّذِيٓ أَنشَأَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ فَمُسۡتَقَرّٞ وَمُسۡتَوۡدَعٞۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَفۡقَهُونَ","aya_text_emlaey":"وهو الذي أنشأكم من نفس واحدة فمستقر ومستودع قد فصلنا الآيات لقوم يفقهون","aya_tafseer":"[98] والله سبحانه هو الذي ابتدأ خلقكم - أيها الناس - من آدم عليه السلام؛ إذ خلقه مِن طين، ثم كنتم سلالة ونسلاً منه، فجعل لكم مستقَرّاً تستقرون فيه، وهو أرحام النساء، ومستودعاً تُحفَظُون فيه، وهو أصلاب الرجال، قد بيَّنَّا الحجج وميَّزنا الأدلة، وأحكمناها لقوم يفهمون مواقع الحجج ومواضع العبر."},{"id":"888","jozz":"7","page":"140","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"12","aya_no":"99","aya_text":"وَهُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءٖ فَأَخۡرَجۡنَا مِنۡهُ خَضِرٗا نُّخۡرِجُ مِنۡهُ حَبّٗا مُّتَرَاكِبٗا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ وَجَنَّٰتٖ مِّنۡ أَعۡنَابٖ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهٗا وَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ","aya_text_emlaey":"وهو الذي أنـزل من السماء ماء فأخرجنا به نبات كل شيء فأخرجنا منه خضرا نخرج منه حبا متراكبا ومن النخل من طلعها قنوان دانية وجنات من أعناب والزيتون والرمان مشتبها وغير متشابه انظروا إلى ثمره إذا أثمر وينعه إن في ذلكم لآيات لقوم يؤمنون","aya_tafseer":"[99] والله سبحانه هو الذي أنزل من السحاب مطراً فأخرج به نبات كل شيء، فأخرج من النبات زرعاً وشجراً أخضر، ثم أخرج من الزرع حبّاً يركب بعضه بعضاً، كسنابل القمح والشعير والأُرْزِ، وأخرج من طلع النخل -وهو الغِلاف الذي ينشأ فيه أول ثمر النَّخل- عذوقاً بما فيها من الرُّطب قريبة التناول، وأخرج سبحانه بساتين من أعناب، وأخرج شجر الزيتون والرمان الذي يتشابه في ورقه ويختلف في ثمره شكلاً وطعماً وطبعاً. انظروا أيها الناس إلى ثمر هذا النبات إذا أثمر، وإلى نضجه وبلوغه حين يبلغ. إن في ذلكم -أيها الناس- لدلالات على كمال قدرة خالق هذه الأشياء وحكمته ورحمته لقوم يصدقون به تعالى ويعملون بشرعه."},{"id":"889","jozz":"7","page":"140","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"13","aya_no":"100","aya_text":"وَجَعَلُواْ لِلَّهِ شُرَكَآءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ وَخَرَقُواْ لَهُۥ بَنِينَ وَبَنَٰتِۭ بِغَيۡرِ عِلۡمٖۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ","aya_text_emlaey":"وجعلوا لله شركاء الجن وخلقهم وخرقوا له بنين وبنات بغير علم سبحانه وتعالى عما يصفون","aya_tafseer":"[100] وجعل هؤلاء المشركون الجن شركاء لله تعالى في العبادة؛ اعتقاداً منهم أنهم ينفعون أو يضرون، وقد خلقهم الله تعالى وما يعبدون من العدم، فهو المستقل بالخلق وحده، فيجب أن يستقل بالعبادة وحده لا شريك له. ولقد كذب هؤلاء المشركون على الله تعالى حين نسبوا إليه البنين والبنات؛ جهلاً منهم بما يجب له من صفات الكمال، تنزَّه وعلا عما نسبه إليه المشركون من ذلك الكذب والافتراء."},{"id":"890","jozz":"7","page":"140","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"14","line_end":"15","aya_no":"101","aya_text":"بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَيۡءٖۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ","aya_text_emlaey":"بديع السموات والأرض أنى يكون له ولد ولم تكن له صاحبة وخلق كل شيء وهو بكل شيء عليم","aya_tafseer":"[101] والله تعالى هو الذي أوجد السموات والأرض وما فيهن على غير مثال سابق، كيف يكون له ولد ولم تكن له صاحبة؟ تعالى الله عما يقول المشركون علوّاً كبيراً، وهو الذي خلق كل شيء من العدم، ولا يخفى عليه شيء من أمور الخلق."},{"id":"891","jozz":"7","page":"141","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"102","aya_text":"ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ","aya_text_emlaey":"ذلكم الله ربكم لا إله إلا هو خالق كل شيء فاعبدوه وهو على كل شيء وكيل","aya_tafseer":"[102] ذلكم -أيها المشركون- هو ربكم جل وعلا، لا معبود بحق سواه، خالق كل شيء فانقادوا واخضعوا له بالطاعة والعبادة. وهو سبحانه على كل شيء وكيل وحفيظ، يدبر أمور خلقه."},{"id":"892","jozz":"7","page":"141","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"3","aya_no":"103","aya_text":"لَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ","aya_text_emlaey":"لا تدركه الأبصار وهو يدرك الأبصار وهو اللطيف الخبير","aya_tafseer":"[103] لا تحيط الأبصارُ بالله -وإن كان المؤمنون في الدار الآخرة يرون ربهم بغير إحاطة- وهو سبحانه يدرك الأبصار ويحيط بها، ويعلمها على ما هي عليه، وهو اللطيف بأوليائه الذي يعلم دقائق الأشياء، الخبير الذي يعلم بواطنها."},{"id":"893","jozz":"7","page":"141","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"3","line_end":"5","aya_no":"104","aya_text":"قَدۡ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِيَ فَعَلَيۡهَاۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ","aya_text_emlaey":"قد جاءكم بصائر من ربكم فمن أبصر فلنفسه ومن عمي فعليها وما أنا عليكم بحفيظ","aya_tafseer":"[104] قل -أيها الرسول- لهؤلاء المشركين: قد جاءتكم براهين ظاهرة تبصرون بها الهدى من الضلال، مما اشتمل عليها القرآن، وجاء بها الرسول عليه الصلاة والسلام، فمَن تبيَّن هذه البراهين وآمن بمدلولها فَنَفْعُ ذلك لنفسه، ومَن لم يبصر الهدى بعد ظهور الحجة عليه فعلى نفسه جنى، وما أنا عليكم بحافظ أحصي أعمالكم، وإنما أنا مبلغ، والله يهدي مَن يشاء ويضل من يشاء وَفْقَ علمه وحكمته."},{"id":"894","jozz":"7","page":"141","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"6","aya_no":"105","aya_text":"وَكَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ وَلِيَقُولُواْ دَرَسۡتَ وَلِنُبَيِّنَهُۥ لِقَوۡمٖ يَعۡلَمُونَ","aya_text_emlaey":"وكذلك نصرف الآيات وليقولوا درست ولنبينه لقوم يعلمون","aya_tafseer":"[105] وكما بيَّنَّا في هذا القرآن للمشركين البراهين الظاهرة في أمر التوحيد والنبوة والمعاد، نبيِّن لهم البراهين في كل ما جهلوه فيقولون عند ذلك كذباً: تعلمتَ من أهل الكتاب، ولنبين -بتصريفنا الآيات- الحقَّ لقوم يعلمونه، فيقبلونه ويتبعونه، وهم المؤمنون برسول الله محمد -صلى الله عليه وسلم- وما أنزل عليه."},{"id":"895","jozz":"7","page":"141","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"7","aya_no":"106","aya_text":"ٱتَّبِعۡ مَآ أُوحِيَ إِلَيۡكَ مِن رَّبِّكَۖ لَآ إِلَٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"اتبع ما أوحي إليك من ربك لا إله إلا هو وأعرض عن المشركين","aya_tafseer":"[106] اتبع -أيها الرسول- ما أوحيناه إليك من الأوامر والنواهي التي أعظمُها توحيدُ الله سبحانه والدعوة إليه، ولا تُبال بعناد المشركين، وادعائهم الباطل."},{"id":"896","jozz":"7","page":"141","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"8","line_end":"9","aya_no":"107","aya_text":"وَلَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكُواْۗ وَمَا جَعَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٖ","aya_text_emlaey":"ولو شاء الله ما أشركوا وما جعلناك عليهم حفيظا وما أنت عليهم بوكيل","aya_tafseer":"[107] ولو شاء الله تعالى أن لا يشرك هؤلاء المشركون لمَا أشركوا، لكنه تعالى عليم بما سيكون من سوء اختيارهم واتباعهم أهواءهم المنحرفة. وما جعلناك -أيها الرسول- عليهم رقيباً تحفظ عليهم أعمالهم، وما أنت بقَيِّمٍ عليهم تدبر مصالحهم."},{"id":"897","jozz":"7","page":"141","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"11","aya_no":"108","aya_text":"وَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمٖۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم كذلك زينا لكل أمة عملهم ثم إلى ربهم مرجعهم فينبئهم بما كانوا يعملون","aya_tafseer":"[108] ولا تسبوا -أيها المسلمون- الأوثان التي يعبدها المشركون -سدّاً للذريعة- حتى لا يتسبب ذلك في سبهم الله جهلاً واعتداءً بغير علم. وكما حسَّنَّا لهؤلاء عملهم السيِّئ عقوبة لهم على سوء اختيارهم، حسَّنَّا لكل أمة أعمالها، ثم إلى ربهم معادهم جميعاً فيخبرهم بأعمالهم التي كانوا يعملونها في الدنيا، ثم يجازيهم بها."},{"id":"898","jozz":"7","page":"141","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"14","aya_no":"109","aya_text":"وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَتۡهُمۡ ءَايَةٞ لَّيُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِۖ وَمَا يُشۡعِرُكُمۡ أَنَّهَآ إِذَا جَآءَتۡ لَا يُؤۡمِنُونَ","aya_text_emlaey":"وأقسموا بالله جهد أيمانهم لئن جاءتهم آية ليؤمنن بها قل إنما الآيات عند الله وما يشعركم أنها إذا جاءت لا يؤمنون","aya_tafseer":"[109] وأقسم هؤلاء المشركون بأيمان مؤكَّدة: لئن جاءنا محمد بعلامة خارقة لنصدقنَّ بما جاء به، قل -أيها الرسول-: إنما مجيء المعجزات الخارقة من عند الله تعالى، هو القادر على المجيء بها إذا شاء، وما يدريكم أيها المؤمنون: لعل هذه المعجزات إذا جاءت لا يصدِّق بها هؤلاء المشركون."},{"id":"899","jozz":"7","page":"141","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"14","line_end":"15","aya_no":"110","aya_text":"وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ وَأَبۡصَٰرَهُمۡ كَمَا لَمۡ يُؤۡمِنُواْ بِهِۦٓ أَوَّلَ مَرَّةٖ وَنَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ","aya_text_emlaey":"ونقلب أفئدتهم وأبصارهم كما لم يؤمنوا به أول مرة ونذرهم في طغيانهم يعمهون","aya_tafseer":"[110] ونقلب أفئدتهم وأبصارهم، فنحول بينها وبين الانتفاع بآيات الله، فلا يؤمنون بها كما لم يؤمنوا بآيات القرآن عند نزولها أول مرة، ونتركهم في تمرُّدهم على الله متحيِّرين، لا يهتدون إلى الحق والصواب."},{"id":"900","jozz":"8","page":"142","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"3","aya_no":"111","aya_text":"۞ وَلَوۡ أَنَّنَا نَزَّلۡنَآ إِلَيۡهِمُ ٱلۡمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَيۡهِمۡ كُلَّ شَيۡءٖ قُبُلٗا مَّا كَانُواْ لِيُؤۡمِنُوٓاْ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكۡثَرَهُمۡ يَجۡهَلُونَ","aya_text_emlaey":"ولو أننا نـزلنا إليهم الملائكة وكلمهم الموتى وحشرنا عليهم كل شيء قبلا ما كانوا ليؤمنوا إلا أن يشاء الله ولكن أكثرهم يجهلون","aya_tafseer":"[111] ولو أننا أجبنا طلب هؤلاء المشركين، فنزَّلنا إليهم الملائكة من السماء، وأحيينا لهم الموتى، فكلَّموهم، وجمعنا لهم كل شيء طلبوه فعاينوه مواجهة، لم يصدِّقوا بما دعوتهم إليه -أيها الرسول- ولم يعملوا به، إلا من شاء الله له الهداية، ولكن أكثر هؤلاء الكفار يجهلون الحق الذي جئت به من عند الله تعالى."},{"id":"901","jozz":"8","page":"142","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"3","line_end":"6","aya_no":"112","aya_text":"وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ وَلَوۡ شَآءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ","aya_text_emlaey":"وكذلك جعلنا لكل نبي عدوا شياطين الإنس والجن يوحي بعضهم إلى بعض زخرف القول غرورا ولو شاء ربك ما فعلوه فذرهم وما يفترون","aya_tafseer":"[112] وكما ابتليناك -أيها الرسول- بأعدائك من المشركين ابتلينا جميع الأنبياء -عليهم السلام- بأعداء مِن مَرَدَة قومهم وأعداء من مَرَدَة الجن، يُلقي بعضهم إلى بعض القول الذي زيَّنوه بالباطل؛ ليغتر به سامعه، فيضل عن سبيل الله. ولو أراد ربك -جلَّ وعلا- لحال بينهم وبين تلك العداوة، ولكنه الابتلاء من الله، فدَعْهم وما يختلقون مِن كذب وزور."},{"id":"902","jozz":"8","page":"142","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"7","aya_no":"113","aya_text":"وَلِتَصۡغَىٰٓ إِلَيۡهِ أَفۡـِٔدَةُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَلِيَرۡضَوۡهُ وَلِيَقۡتَرِفُواْ مَا هُم مُّقۡتَرِفُونَ","aya_text_emlaey":"ولتصغى إليه أفئدة الذين لا يؤمنون بالآخرة وليرضوه وليقترفوا ما هم مقترفون","aya_tafseer":"[113] ولِتميل إليه قلوب الكفار الذين لا يصدقون بالحياة الآخرة ولا يعملون لها، ولتحبَّه أنفسهم، وليكتسبوا من الأعمال السيئة ما هم مكتسبون. وفي هذا تهديد عظيم لهم."},{"id":"903","jozz":"8","page":"142","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"10","aya_no":"114","aya_text":"أَفَغَيۡرَ ٱللَّهِ أَبۡتَغِي حَكَمٗا وَهُوَ ٱلَّذِيٓ أَنزَلَ إِلَيۡكُمُ ٱلۡكِتَٰبَ مُفَصَّلٗاۚ وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡلَمُونَ أَنَّهُۥ مُنَزَّلٞ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ","aya_text_emlaey":"أفغير الله أبتغي حكما وهو الذي أنـزل إليكم الكتاب مفصلا والذين آتيناهم الكتاب يعلمون أنه منـزل من ربك بالحق فلا تكونن من الممترين","aya_tafseer":"[114] قل -أيها الرسول- لهؤلاء المشركين: أغير الله إلهي وإلهكم أطلب حَكَماً بيني وبينكم، وهو سبحانه الذي أنزل إليكم القرآن مبيناً فيه الحكم فيما تختصمون فيه من أمري وأمركم؟ وبنو إسرائيل الذين آتاهم الله التوراة والإنجيل يعلمون علماً يقيناً أن هذا القرآن منزل عليك -أيها الرسول- من ربك بالحق، فلا تكوننَّ من الشاكِّين في شيء مما أوحينا إليك."},{"id":"904","jozz":"8","page":"142","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"11","aya_no":"115","aya_text":"وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","aya_text_emlaey":"وتمت كلمت ربك صدقا وعدلا لا مبدل لكلماته وهو السميع العليم","aya_tafseer":"[115] وتمت كلمة ربك -وهي القرآن- صدقاً في الأخبار والأقوال، وعدلاً في الأحكام، فلا يستطيع أحد أن يبدِّل كلماته الكاملة. والله تعالى هو السميع لما يقول عباده، العليم ببواطن أمورهم وظواهرها."},{"id":"905","jozz":"8","page":"142","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"13","aya_no":"116","aya_text":"وَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ","aya_text_emlaey":"وإن تطع أكثر من في الأرض يضلوك عن سبيل الله إن يتبعون إلا الظن وإن هم إلا يخرصون","aya_tafseer":"[116] ولو فُرض -أيها الرسول- أنك أطعت أكثر أهل الأرض لأضلُّوك عن دين الله، ما يسيرون إلا على ما ظنوه حقّاً بتقليدهم أسلافهم، وما هم إلا يظنون ويكذبون."},{"id":"906","jozz":"8","page":"142","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"14","aya_no":"117","aya_text":"إِنَّ رَبَّكَ هُوَ أَعۡلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ","aya_text_emlaey":"إن ربك هو أعلم من يضل عن سبيله وهو أعلم بالمهتدين","aya_tafseer":"[117] إن ربك هو أعلم بالضالين عن سبيل الرشاد، وهو أعلم منكم ومنهم بمن كان على استقامة وسداد، لا يخفى عليه منهم أحد."},{"id":"907","jozz":"8","page":"142","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"14","line_end":"15","aya_no":"118","aya_text":"فَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ","aya_text_emlaey":"فكلوا مما ذكر اسم الله عليه إن كنتم بآياته مؤمنين","aya_tafseer":"[118] فكلوا من الذبائح التي ذُكِرَ اسم الله عليها، إن كنتم ببراهين الله تعالى الواضحة مصدقين."},{"id":"908","jozz":"8","page":"143","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"3","aya_no":"119","aya_text":"وَمَا لَكُمۡ أَلَّا تَأۡكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَيۡهِۗ وَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ","aya_text_emlaey":"وما لكم ألا تأكلوا مما ذكر اسم الله عليه وقد فصل لكم ما حرم عليكم إلا ما اضطررتم إليه وإن كثيرا ليضلون بأهوائهم بغير علم إن ربك هو أعلم بالمعتدين","aya_tafseer":"[119] وأيُّ شيء يمنعكم - أيها المسلمون - من أن تأكلوا مما ذكر اسم الله عليه، وقد بيَّن الله سبحانه لكم جميع ما حَرَّم عليكم؟ لكن ما دعت إليه الضرورة بسبب المجاعة، مما هو محرم عليكم كالميتة، فإنه مباح لكم. وإن كثيراً من الضالين ليُضلون عن سبيل الله أشياعَهم في تحليل الحرام وتحريم الحلال بأهوائهم؛ جهلاً منهم. إن ربك -أيها الرسول- هو أعلم بمن تجاوز حده في ذلك، وهو الذي يتولى حسابه وجزاءه."},{"id":"909","jozz":"8","page":"143","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"5","aya_no":"120","aya_text":"وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ","aya_text_emlaey":"وذروا ظاهر الإثم وباطنه إن الذين يكسبون الإثم سيجزون بما كانوا يقترفون","aya_tafseer":"[120] واتركوا -أيها الناس- جميع المعاصي، ما كان منها علانية وما كان سرّاً. إن الذين يفعلون المعاصي سيعاقبهم ربهم؛ بسبب ما كانوا يعملونه من السيئات."},{"id":"910","jozz":"8","page":"143","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"7","aya_no":"121","aya_text":"وَلَا تَأۡكُلُواْ مِمَّا لَمۡ يُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَيۡهِ وَإِنَّهُۥ لَفِسۡقٞۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ","aya_text_emlaey":"ولا تأكلوا مما لم يذكر اسم الله عليه وإنه لفسق وإن الشياطين ليوحون إلى أوليائهم ليجادلوكم وإن أطعتموهم إنكم لمشركون","aya_tafseer":"[121] ولا تأكلوا -أيها المسلمون- من الذبائح التي لم يذكر اسم الله عليها عند الذبح، كالميتة وما ذبح للأوثان والجن، وغير ذلك، وإن الأكل من تلك الذبائح لَخروج عن طاعة الله تعالى. وإن مَرَدَة الجن لَيُلْقون إلى أوليائهم من شياطين الإنس بالشبهات حول تحريم أكل الميتة، فيأمرونهم أن يقولوا للمسلمين في جدالهم معهم: إنكم بعدم أكلكم الميتة لا تأكلون ما قتله الله، بينما تأكلون مما تذبحونه، وإن أطعتموهم -أيها المسلمون في تحليل الميتة- فأنتم وهم في الشرك سواء."},{"id":"911","jozz":"8","page":"143","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"8","line_end":"10","aya_no":"122","aya_text":"أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ وَجَعَلۡنَا لَهُۥ نُورٗا يَمۡشِي بِهِۦ فِي ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِي ٱلظُّلُمَٰتِ لَيۡسَ بِخَارِجٖ مِّنۡهَاۚ كَذَٰلِكَ زُيِّنَ لِلۡكَٰفِرِينَ مَا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"أو من كان ميتا فأحييناه وجعلنا له نورا يمشي به في الناس كمن مثله في الظلمات ليس بخارج منها كذلك زين للكافرين ما كانوا يعملون","aya_tafseer":"[122] أوَمن كان ميتاً في الضلالة هالكاً حائراً، فأحيينا قلبه بالإيمان، وهديناه له، ووفقناه لاتباع رسلنا، فأصبح يعيش في أنوار الهداية، كمن مثله في الجهالات والأهواء والضلالات المتفرقة، لا يهتدي إلى منفذ، ولا مُخَلِّص له مما هو فيه؟ لا يستويان، وكما خذلتُ هذا الكافر الذي يجادلكم -أيها المؤمنون- فزيَّنْتُ له سوء عمله، فرآه حسناً، زيَّنتُ للجاحدين أعمالهم السيئة؛ ليستوجبوا بذلك العذابَ."},{"id":"912","jozz":"8","page":"143","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"12","aya_no":"123","aya_text":"وَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ مُجۡرِمِيهَا لِيَمۡكُرُواْ فِيهَاۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا يَشۡعُرُونَ","aya_text_emlaey":"وكذلك جعلنا في كل قرية أكابر مجرميها ليمكروا فيها وما يمكرون إلا بأنفسهم وما يشعرون","aya_tafseer":"[123] ومثل هذا الذي حصل مِن زعماء الكفار في «مكة» من الصدِّ عن دين الله تعالى، جعلنا في كل قرية مجرمين يتزعمهم أكابرهم؛ ليمكروا فيها بالصد عن دين الله، وما يكيدون إلا أنفسهم، وما يُحِسُّون بذلك."},{"id":"913","jozz":"8","page":"143","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"15","aya_no":"124","aya_text":"وَإِذَا جَآءَتۡهُمۡ ءَايَةٞ قَالُواْ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَآ أُوتِيَ رُسُلُ ٱللَّهِۘ ٱللَّهُ أَعۡلَمُ حَيۡثُ يَجۡعَلُ رِسَالَتَهُۥۗ سَيُصِيبُ ٱلَّذِينَ أَجۡرَمُواْ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٞ شَدِيدُۢ بِمَا كَانُواْ يَمۡكُرُونَ","aya_text_emlaey":"وإذا جاءتهم آية قالوا لن نؤمن حتى نؤتى مثل ما أوتي رسل الله الله أعلم حيث يجعل رسالته سيصيب الذين أجرموا صغار عند الله وعذاب شديد بما كانوا يمكرون","aya_tafseer":"[124] وإذا جاءت هؤلاء المشركين من أهل «مكة» حجة ظاهرة على نبوة محمد -صلى الله عليه وسلم-، قال بعض كبرائهم: لن نصدِّق بنبوته حتى يعطينا الله من النبوة والمعجزات مثل ما أعطى رسله السابقين. فردَّ الله تعالى عليهم بقوله: الله أعلم حيث يجعل رسالته، أي: بالذين هم أهل لحمل رسالته وتبليغها إلى الناس. سينال هؤلاء الطغاة الذل، ولهم عذاب موجع في نار جهنم؛ بسبب كيدهم للإسلام وأهله."},{"id":"914","jozz":"8","page":"144","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"4","aya_no":"125","aya_text":"فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ","aya_text_emlaey":"فمن يرد الله أن يهديه يشرح صدره للإسلام ومن يرد أن يضله يجعل صدره ضيقا حرجا كأنما يصعد في السماء كذلك يجعل الله الرجس على الذين لا يؤمنون","aya_tafseer":"[125] فمن يشأ الله أن يوفقه لقَبول الحق يشرح صدره للتوحيد والإيمان، ومن يشأ أن يضله يجعل صدره في حال شديدة من الانقباض عن قَبول الهدى، كحال مَن يصعد في طبقات الجو العليا، فيصاب بضيق شديد في التنفس. وكما يجعل الله صدور الكافرين شديدة الضيق والانقباض، كذلك يجعل العذاب على الذين لا يؤمنون به."},{"id":"915","jozz":"8","page":"144","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"5","aya_no":"126","aya_text":"وَهَٰذَا صِرَٰطُ رَبِّكَ مُسۡتَقِيمٗاۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمٖ يَذَّكَّرُونَ","aya_text_emlaey":"وهذا صراط ربك مستقيما قد فصلنا الآيات لقوم يذكرون","aya_tafseer":"[126] وهذا الذي بيَّنَّاه لك -أيها الرسول- هو الطريق الموصل إلى رضا ربك وجنته. قد بينَّا البراهين لمن يتذكر من أهل العقول الراجحة."},{"id":"916","jozz":"8","page":"144","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"6","aya_no":"127","aya_text":"۞ لَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"لهم دار السلام عند ربهم وهو وليهم بما كانوا يعملون","aya_tafseer":"[127] للمتذكرين عند ربهم جل وعلا يوم القيامة دار السلامة والأمان من كل مكروه وهي الجنة، وهو سبحانه ناصرهم وحافظهم جزاءً لهم؛ بسبب أعمالهم الصالحة."},{"id":"917","jozz":"8","page":"144","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"10","aya_no":"128","aya_text":"وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعٗا يَٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِيَآؤُهُم مِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضٖ وَبَلَغۡنَآ أَجَلَنَا ٱلَّذِيٓ أَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٞ","aya_text_emlaey":"ويوم يحشرهم جميعا يامعشر الجن قد استكثرتم من الإنس وقال أولياؤهم من الإنس ربنا استمتع بعضنا ببعض وبلغنا أجلنا الذي أجلت لنا قال النار مثواكم خالدين فيها إلا ما شاء الله إن ربك حكيم عليم","aya_tafseer":"[128] واذكر -أيها الرسول- يوم يحشر الله تعالى الكفار وأولياءهم من شياطين الجن فيقول: يا معشر الجن قد أضللتم كثيراً من الإنس، وقال أولياؤهم من كفار الإنس: ربنا قد انتفع بعضنا من بعض، وبلغنا الأجل الذي أجَّلْتَه لنا بانقضاء حياتنا الدنيا، قال الله تعالى لهم: النار مثواكم، أي: مكان إقامتكم خالدين فيها، إلا مَن شاء الله عدم خلوده فيها مِن عصاة الموحدين. إن ربك حكيم في تدبيره وصنعه، عليم بجميع أمور عباده."},{"id":"918","jozz":"8","page":"144","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"11","aya_no":"129","aya_text":"وَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ","aya_text_emlaey":"وكذلك نولي بعض الظالمين بعضا بما كانوا يكسبون","aya_tafseer":"[129] وكما سَلَّطْنا شياطين الجن على كفار الإنس، فكانوا أولياء لهم، نسلِّط الظالمين من الإنس بعضهم على بعض في الدنيا؛ بسبب ما يعملونه من المعاصي."},{"id":"919","jozz":"8","page":"144","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"15","aya_no":"130","aya_text":"يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ","aya_text_emlaey":"يامعشر الجن والإنس ألم يأتكم رسل منكم يقصون عليكم آياتي وينذرونكم لقاء يومكم هذا قالوا شهدنا على أنفسنا وغرتهم الحياة الدنيا وشهدوا على أنفسهم أنهم كانوا كافرين","aya_tafseer":"[130] أيها المشركون من الجن والإنس، ألم يأتكم رسل من جملتكم -وظاهر النصوص يدلُّ على أنَّ الرسل من الإنس فقط-، يخبرونكم بآياتي الواضحة المشتملة على الأمر والنهي، وبيانِ الخير والشر، ويحذرونكم لقاء عذابي في يوم القيامة؟ قال هؤلاء المشركون من الإنس والجن: شَهِدْنا على أنفسنا بأن رسلك قد بلغونا آياتك، وأنذرونا لقاء يومنا هذا، فكذبناهم، وخدعت هؤلاء المشركين زينةُ الحياة الدنيا، وشهدوا على أنفسهم أنهم كانوا جاحدين وحدانية الله تعالى ومكذبين لرسله عليهم السلام."},{"id":"920","jozz":"8","page":"145","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"131","aya_text":"ذَٰلِكَ أَن لَّمۡ يَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمٖ وَأَهۡلُهَا غَٰفِلُونَ","aya_text_emlaey":"ذلك أن لم يكن ربك مهلك القرى بظلم وأهلها غافلون","aya_tafseer":"[131] إنما أعذرنا إلى الثقلين بإرسال الرسل وإنزال الكتب؛ لئلا يؤاخَذَ أحد بظلمه، وهو لم تبلغه دعوة، ولكن أعذرنا إلى الأمم، وما عذَّبنا أحداً إلا بعد إرسال الرسل إليهم."},{"id":"921","jozz":"8","page":"145","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"3","aya_no":"132","aya_text":"وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ","aya_text_emlaey":"ولكل درجات مما عملوا وما ربك بغافل عما يعملون","aya_tafseer":"[132] ولكل عامل في طاعة الله تعالى أو معصيته مراتب من عمله، يبلِّغه الله إياها، ويجازيه عليها. وما ربك -أيها الرسول- بغافل عما يعمل عباده."},{"id":"922","jozz":"8","page":"145","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"3","line_end":"5","aya_no":"133","aya_text":"وَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ","aya_text_emlaey":"وربك الغني ذو الرحمة إن يشأ يذهبكم ويستخلف من بعدكم ما يشاء كما أنشأكم من ذرية قوم آخرين","aya_tafseer":"[133] وربك -أيها الرسول- الذي أمر الناس بعبادته، هو الغني وحده، وكل خلقه محتاجون إليه، وهو سبحانه ذو الرحمة الواسعة، لو أراد لأهلككم، وأوجد قوماً غيركم يَخلُفونكم من بعد فنائكم، ويعملون بطاعته تعالى، كما أوجدكم من نسل قوم آخرين كانوا قبلكم."},{"id":"923","jozz":"8","page":"145","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"6","aya_no":"134","aya_text":"إِنَّ مَا تُوعَدُونَ لَأٓتٖۖ وَمَآ أَنتُم بِمُعۡجِزِينَ","aya_text_emlaey":"إن ما توعدون لآت وما أنتم بمعجزين","aya_tafseer":"[134] إن الذي يُوعِدُكم به ربكم -أيها المشركون- من العقاب على كفركم واقع بكم، ولن تُعجِزوا ربكم هرباً، فهو قادر على إعادتكم، وإن صرتم تراباً وعظاماً."},{"id":"924","jozz":"8","page":"145","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"8","aya_no":"135","aya_text":"قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَامِلٞۖ فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ","aya_text_emlaey":"قل ياقوم اعملوا على مكانتكم إني عامل فسوف تعلمون من تكون له عاقبة الدار إنه لا يفلح الظالمون","aya_tafseer":"[135] قل -أيها الرسول-: يا قوم اعملوا على طريقتكم فإني عامل على طريقتي التي شرعها لي ربي جل وعلا، فسوف تعلمون -عند حلول النِّقْمة بكم- مَنِ الذي تكون له العاقبة الحسنة؟ إنه لا يفوز برضوان الله تعالى والجنة مَن تجاوز حده وظلم، فأشرك مع الله غيره."},{"id":"925","jozz":"8","page":"145","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"12","aya_no":"136","aya_text":"وَجَعَلُواْ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَٰمِ نَصِيبٗا فَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ سَآءَ مَا يَحۡكُمُونَ","aya_text_emlaey":"وجعلوا لله مما ذرأ من الحرث والأنعام نصيبا فقالوا هذا لله بزعمهم وهذا لشركائنا فما كان لشركائهم فلا يصل إلى الله وما كان لله فهو يصل إلى شركائهم ساء ما يحكمون","aya_tafseer":"[136] وجعل المشركون لله -جلَّ وعلا- جزءاً مما خلق من الزروع والثمار والأنعام يقدمونه للضيوف والمساكين، وجعلوا قسماً آخر من هذه الأشياء لشركائهم من الأوثان والأنصاب، فما كان مخصصاً لشركائهم فإنه يصل إليها وحدها، ولا يصل إلى الله، وما كان مخصصاً لله تعالى فإنه يصل إلى شركائهم. بئس حكم القوم وقسمتهم."},{"id":"926","jozz":"8","page":"145","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"15","aya_no":"137","aya_text":"وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ","aya_text_emlaey":"وكذلك زين لكثير من المشركين قتل أولادهم شركاؤهم ليردوهم وليلبسوا عليهم دينهم ولو شاء الله ما فعلوه فذرهم وما يفترون","aya_tafseer":"[137] وكما زيَّن الشيطان للمشركين أن يجعلوا لله تعالى من الزَّرع والأنعام نصيباً، ولشركائهم نصيباً، زيَّنت الشياطين لكثير من المشركين قَتْلَ أولادهم خشية الفقر؛ ليوقعوا هؤلاء الآباء في الهلاك بقتل النفس التي حرم الله قتلها إلا بالحق، وليخلطوا عليهم دينهم فيلتبس، فيضلوا ويهلكوا، ولو شاء الله ألا يفعلوا ذلك ما فعلوه، ولكنه قَدَّر ذلك لعلمه بسوء حالهم ومآلهم، فاتركهم -أيها الرسول- وشأنهم فيما يفترون من كذب، فسيحكم الله بينك وبينهم."},{"id":"927","jozz":"8","page":"146","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"4","aya_no":"138","aya_text":"وَقَالُواْ هَٰذِهِۦٓ أَنۡعَٰمٞ وَحَرۡثٌ حِجۡرٞ لَّا يَطۡعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعۡمِهِمۡ وَأَنۡعَٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَٰمٞ لَّا يَذۡكُرُونَ ٱسۡمَ ٱللَّهِ عَلَيۡهَا ٱفۡتِرَآءً عَلَيۡهِۚ سَيَجۡزِيهِم بِمَا كَانُواْ يَفۡتَرُونَ","aya_text_emlaey":"وقالوا هذه أنعام وحرث حجر لا يطعمها إلا من نشاء بزعمهم وأنعام حرمت ظهورها وأنعام لا يذكرون اسم الله عليها افتراء عليه سيجزيهم بما كانوا يفترون","aya_tafseer":"[138] وقال المشركون: هذه إبل وزرع حرام، لا يأكلها إلا مَن يأذنون له -حسب ادعائهم- مِن سدنة الأوثان وغيرهم.وهذه إبل حُرِّمت ظهورها، فلا يحل ركوبها والحملُ عليها بحالٍ من الأحوال.وهذه إبل لا يَذكرون اسم الله تعالى عليها في أي شأن من شؤونها. فعلوا ذلك كذباً منهم على الله، سيجزيهم الله بسبب ما كانوا يفترون من كذبٍ عليه سبحانه."},{"id":"928","jozz":"8","page":"146","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"7","aya_no":"139","aya_text":"وَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ","aya_text_emlaey":"وقالوا ما في بطون هذه الأنعام خالصة لذكورنا ومحرم على أزواجنا وإن يكن ميتة فهم فيه شركاء سيجزيهم وصفهم إنه حكيم عليم","aya_tafseer":"[139] وقال المشركون: ما في بطون الأنعام من أجنَّة مباح لرجالنا، ومحرم على نسائنا، إذا ولد حيّاً، ويشتركون فيه إذا ولد ميتاً. سيعاقبهم الله إذ شرَّعوا لأنفسهم من التحليل والتحريم مالم يأذن به الله. إنه تعالى حكيم في تدبير أمور خلقه، عليم بهم."},{"id":"929","jozz":"8","page":"146","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"9","aya_no":"140","aya_text":"قَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ","aya_text_emlaey":"قد خسر الذين قتلوا أولادهم سفها بغير علم وحرموا ما رزقهم الله افتراء على الله قد ضلوا وما كانوا مهتدين","aya_tafseer":"[140] قد خسر وهلك الذين قتلوا أولادهم لضعف عقولهم وجهلهم، وحَرَّموا ما رزقهم الله كذباً على الله. قد بَعُدوا عن الحق، وما كانوا من أهل الهدى والرشاد. فالحلال ما أحلَّه الله، والحرام ما حَرَّمه الله، وليس لأحد مِن خَلْقه فرداً كان أو جماعة أن يشرع لعباده ما لم يأذن به الله."},{"id":"930","jozz":"8","page":"146","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"13","aya_no":"141","aya_text":"۞ وَهُوَ ٱلَّذِيٓ أَنشَأَ جَنَّٰتٖ مَّعۡرُوشَٰتٖ وَغَيۡرَ مَعۡرُوشَٰتٖ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهٗا وَغَيۡرَ مُتَشَٰبِهٖۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ","aya_text_emlaey":"وهو الذي أنشأ جنات معروشات وغير معروشات والنخل والزرع مختلفا أكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره إذا أثمر وآتوا حقه يوم حصاده ولا تسرفوا إنه لا يحب المسرفين","aya_tafseer":"[141] والله سبحانه وتعالى هو الذي أوجد لكم بساتين: منها ما هو مرفوع عن الأرض كالأعناب، ومنها ما هو غير مرفوع، ولكنه قائم على سوقه كالنخل والزرع، متنوعاً طعمه، والزيتون والرُّمَّان متشابهاً منظره، ومختلفاً ثمره وطعمه. كلوا -أيها الناس- مِن ثمره إذا أثمر، وأعطوا زكاته المفروضة عليكم يوم قِطافه وحصاده، ولا تتجاوزوا حدود الاعتدال في إخراج المال وأكل الطعام وغير ذلك. إنه تعالى لا يحب المتجاوزين حدوده بإنفاق المال في غير وجهه."},{"id":"931","jozz":"8","page":"146","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"15","aya_no":"142","aya_text":"وَمِنَ ٱلۡأَنۡعَٰمِ حَمُولَةٗ وَفَرۡشٗاۚ كُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ","aya_text_emlaey":"ومن الأنعام حمولة وفرشا كلوا مما رزقكم الله ولا تتبعوا خطوات الشيطان إنه لكم عدو مبين","aya_tafseer":"[142] وأوجد من الأنعام ما هو مهيَّأ للحمل عليه لكبره وارتفاعه كالإبل، ومنها ما هو مهيَّأ لغير الحمل لصغره وقربه من الأرض كالبقر والغنم، كلوا مما أباحه الله لكم وأعطاكموه من هذه الأنعام، ولا تحرموا ما أحلَّ الله منها اتباعاً لطرق الشيطان، كما فعل المشركون. إن الشيطان لكم عدو ظاهر العداوة."},{"id":"932","jozz":"8","page":"147","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"3","aya_no":"143","aya_text":"ثَمَٰنِيَةَ أَزۡوَٰجٖۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَيۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ نَبِّـُٔونِي بِعِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"ثمانية أزواج من الضأن اثنين ومن المعز اثنين قل آلذكرين حرم أم الأنثيين أما اشتملت عليه أرحام الأنثيين نبئوني بعلم إن كنتم صادقين","aya_tafseer":"[143] هذه الأنعام التي رزقها الله عباده من الإبل والبقر والغنم ثمانية أصناف: أربعة منها من الغنم، وهي الضأن ذكوراً وإناثاً، والمعز ذكوراً وإناثاً. قل -أيها الرسول- لأولئك المشركين: هل حَرَّم الله الذكرين من الغنم؟ فإن قالوا: نعم، فقد كذبوا في ذلك؛ لأنهم لا يحرمون كل ذكر من الضأن والمعز، وقل لهم: هل حَرَّم الله الأنثيين من الغنم؟ فإن قالوا: نعم، فقد كذبوا أيضاً؛ لأنهم لا يحرمون كل أنثى من ولد الضأن والمعز، وقل لهم: هل حَرَّم الله ما اشتملت عليه أرحام الأنثيين من الضأن والمعز من الحمل؟ فإن قالوا: نعم، فقد كذبوا أيضاً؛ لأنهم لا يحرمون كل حَمْل مِن ذلك، خبِّروني بعلم يدل على صحة ما ذهبتم إليه، إن كنتم صادقين فيما تنسبونه إلى ربكم."},{"id":"933","jozz":"8","page":"147","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"8","aya_no":"144","aya_text":"وَمِنَ ٱلۡإِبِلِ ٱثۡنَيۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَيۡنِۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ ٱلۡأُنثَيَيۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ ٱلۡأُنثَيَيۡنِۖ أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"ومن الإبل اثنين ومن البقر اثنين قل آلذكرين حرم أم الأنثيين أما اشتملت عليه أرحام الأنثيين أم كنتم شهداء إذ وصاكم الله بهذا فمن أظلم ممن افترى على الله كذبا ليضل الناس بغير علم إن الله لا يهدي القوم الظالمين","aya_tafseer":"[144] والأصناف الأربعة الأخرى: هي اثنان من الإبل ذكوراً وإناثاً، واثنان من البقر ذكوراً وإناثاً. قل -أيها الرسول- لأولئك المشركين: أحَرَّم الله الذكرين أم الأنثيين؟ أم حرَّم ما اشتملت عليه أرحام الأنثيين ذكوراً وإناثاً؟ أم كنتم أيها المشركون حاضرين، إذ وصّاكم الله بهذا التحريم للأنعام؟ فلا أحد أشد ظلماً ممن اختلق على الله الكذب؛ ليصرف الناس بجهله عن طريق الهدى. إن الله تعالى لا يوفق للرشد مَن تجاوز حدَّه، فكذب على ربه، وأضلَّ الناس."},{"id":"934","jozz":"8","page":"147","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"8","line_end":"12","aya_no":"145","aya_text":"قُل لَّآ أَجِدُ فِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمٖ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيۡتَةً أَوۡ دَمٗا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرٖ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ رَبَّكَ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنـزير فإنه رجس أو فسقا أهل لغير الله به فمن اضطر غير باغ ولا عاد فإن ربك غفور رحيم","aya_tafseer":"[145] قل -أيها الرسول-: إني لا أجد فيما أوحى الله إليَّ شيئاً محرماً على مَن يأكله مما تذكرون أنه حُرِّم من الأنعام، إلا أن يكون قد مات بغير تذكية، أو يكون دماً مراقاً، أو يكون لحم خنزير فإنه نجس، أو الذي كانت ذكاته خروجاً عن طاعة الله تعالى؛ كما إذا كان المذبوح قد ذكر عليه اسم غير الله عند الذبح. فمن اضطر إلى الأكل من هذه المحرمات؛ بسبب الجوع الشديد غير طالب بأكله منها تلذذاً، ولا متجاوز حد الضرورة، فإن الله تعالى غفور له، رحيم به. وقد ثبت -فيما بعد- بالسنة تحريمُ كلِّ ذي ناب من السباع، ومخلبٍ من الطيرِ، والحمرِ الأهلية، والكلاب."},{"id":"935","jozz":"8","page":"147","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"15","aya_no":"146","aya_text":"وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ","aya_text_emlaey":"وعلى الذين هادوا حرمنا كل ذي ظفر ومن البقر والغنم حرمنا عليهم شحومهما إلا ما حملت ظهورهما أو الحوايا أو ما اختلط بعظم ذلك جزيناهم ببغيهم وإنا لصادقون","aya_tafseer":"[146] واذكر -أيها الرسول- لهؤلاء المشركين ما حَرَّمنا على اليهود من البهائم والطير: وهو كل ما لم يكن مشقوق الأصابع كالإبل والنَّعام، وشحوم البقر والغنم، إلا ما عَلِق من الشحم بظهورها أو أمعائها، أو اختلط بعظم الأَلْية والجنب ونحو ذلك. ذلك التحريم المذكور على اليهود عقوبة مِنَّا لهم بسبب أعمالهم السيئة، وإنَّا لصادقون فيما أخبرنا به عنهم."},{"id":"936","jozz":"8","page":"148","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"2","aya_no":"147","aya_text":"فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةٖ وَٰسِعَةٖ وَلَا يُرَدُّ بَأۡسُهُۥ عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ","aya_text_emlaey":"فإن كذبوك فقل ربكم ذو رحمة واسعة ولا يرد بأسه عن القوم المجرمين","aya_tafseer":"[147] فإن كذبك -أيها الرسول- مخالفوك من المشركين واليهود، وغيرهم، فقل لهم: ربكم جل وعلا ذو رحمة واسعة، ولا يُدْفع عقابه عن القوم الذين أجرموا، فاكتسَبوا الذنوب، واجترحوا السيئات. وفي هذا تهديد لهم لمخالفتهم الرسول -صلى الله عليه وسلم-."},{"id":"937","jozz":"8","page":"148","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"2","line_end":"6","aya_no":"148","aya_text":"سَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءٖۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُواْ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمٖ فَتُخۡرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ","aya_text_emlaey":"سيقول الذين أشركوا لو شاء الله ما أشركنا ولا آباؤنا ولا حرمنا من شيء كذلك كذب الذين من قبلهم حتى ذاقوا بأسنا قل هل عندكم من علم فتخرجوه لنا إن تتبعون إلا الظن وإن أنتم إلا تخرصون","aya_tafseer":"[148] سيقول الذين أشركوا: لو أراد الله أن لا نشرك -نحن وآباؤنا- وأن لا نحرم شيئاً مِن دونه ما فعلنا ذلك، وردَّ الله عليهم ببيان أن هذه الشبهة قد أثارها الكفار مِن قبلهم، وكذَّبوا بها دعوة رسلهم، واستمَرُّوا على ذلك، حتى نزل بهم عذاب الله. قل لهم -أيها الرسول-: هل عندكم -فيما حرَّمتم من الأنعام والزَّرْع، وفيما زعمتم من أن الله قد شاء لكم الكفر، ورضيه منكم وأحبه لكم- من علم صحيح فتظهروه لنا؟ إن تتبعون في أمور هذا الدين إلا مجرد الظن، وإن أنتم إلا تكذبون."},{"id":"938","jozz":"8","page":"148","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"7","aya_no":"149","aya_text":"قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَٰلِغَةُۖ فَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ","aya_text_emlaey":"قل فلله الحجة البالغة فلو شاء لهداكم أجمعين","aya_tafseer":"[149] قل -أيها الرسول- لهم: فلله - جل وعلا - الحجة القاطعة التي يقطع بها ظنونكم، فلو شاء لوفَّقكم جميعاً إلى طريق الاستقامة."},{"id":"939","jozz":"8","page":"148","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"10","aya_no":"150","aya_text":"قُلۡ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَاۖ فَإِن شَهِدُواْ فَلَا تَشۡهَدۡ مَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَهُم بِرَبِّهِمۡ يَعۡدِلُونَ","aya_text_emlaey":"قل هلم شهداءكم الذين يشهدون أن الله حرم هذا فإن شهدوا فلا تشهد معهم ولا تتبع أهواء الذين كذبوا بآياتنا والذين لا يؤمنون بالآخرة وهم بربهم يعدلون","aya_tafseer":"[150] قل -أيها الرسول- لهؤلاء المشركين: هاتوا شهداءكم الذين يشهدون أن الله تعالى هو الذي حَرَّم ما حَرَّمتم من الزَّرع والأنعام، فإن شهدوا -كذباً وزوراً- فلا تصدقهم، ولا توافق الذين حكَّموا أهواءهم، فكذبوا بآيات الله فيما ذهبوا إليه من تحريم ما أحل الله، وتحليل ما حرم الله، ولا تتبع الذين لا يصدقون بالحياة الآخرة ولا يعملون لها، والذين هم بربهم يشركون فيعبدون معه غيره."},{"id":"940","jozz":"8","page":"148","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"15","aya_no":"151","aya_text":"۞ قُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ","aya_text_emlaey":"قل تعالوا أتل ما حرم ربكم عليكم ألا تشركوا به شيئا وبالوالدين إحسانا ولا تقتلوا أولادكم من إملاق نحن نرزقكم وإياهم ولا تقربوا الفواحش ما ظهر منها وما بطن ولا تقتلوا النفس التي حرم الله إلا بالحق ذلكم وصاكم به لعلكم تعقلون","aya_tafseer":"[151] قل -أيها الرسول- لهم: تعالوا أتل ما حَرَّم ربكم عليكم: أن لا تشركوا معه شيئاً من مخلوقاته في عبادته، بل اصرفوا جميع أنواع العبادة له وحده، كالخوف والرجاء والدعاء، وغير ذلك، وأن تحسنوا إلى الوالدين بالبر والدعاء ونحو ذلك من الإحسان، ولا تقتلوا أولادكم مِن أجل فقر نزل بكم؛ فإن الله يرزقكم وإياهم، ولا تقربوا ما كان ظاهراً من كبير الآثام، وما كان خفياً، ولا تقتلوا النفس التي حرم الله قَتْلها إلا بالحق، وذلك في حال القصاص من القاتل، أو الزنى بعد الإحصان، أو الردة عن الإسلام، ذلكم المذكور مما نهاكم الله عنه، وعهد إليكم باجتنابه، ومما أمركم به، وصَّاكم به ربكم؛ لعلكم تعقلون أوامره ونواهيه."},{"id":"941","jozz":"8","page":"149","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"4","aya_no":"152","aya_text":"وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ","aya_text_emlaey":"ولا تقربوا مال اليتيم إلا بالتي هي أحسن حتى يبلغ أشده وأوفوا الكيل والميزان بالقسط لا نكلف نفسا إلا وسعها وإذا قلتم فاعدلوا ولو كان ذا قربى وبعهد الله أوفوا ذلكم وصاكم به لعلكم تذكرون","aya_tafseer":"[152] ولا تقربوا أيها الأوصياء مال مَن مات أبوه وهو صغير إلا بالحال التي تصلح بها أمواله ويَنْتَفِع بها، حتى يصل إلى سن البلوغ ويكون راشداً، فإذا بلغ ذلك فسلموا إليه ماله، وأوفوا الكيل والوزن بالعدل الذي يكون به تمام الوفاء. وإذا بذلتم جهدكم فلا حرج عليكم فيما قد يكون من نقص، لا نكلف نفساً إلا وسعها. وإذا قلتم فتحرَّوا في قولكم العدل دون ميل عن الحق في خبر أو شهادة أو حكم أو شفاعة، ولو كان الذي تعلق به القول ذا قرابة منكم، فلا تميلوا معه بغير حق ، وأوفوا بما عهد الله به إليكم من الالتزام بشريعته. ذلكم المتلوُّ عليكم من الأحكام، وصَّاكم به ربكم؛ رجاء أن تتذكروا عاقبة أمركم."},{"id":"942","jozz":"8","page":"149","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"5","line_end":"7","aya_no":"153","aya_text":"وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ","aya_text_emlaey":"وأن هذا صراطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله ذلكم وصاكم به لعلكم تتقون","aya_tafseer":"[153] ومما وصاكم الله به أن هذا الإسلام هو طريق الله تعالى المستقيم فاسلكوه، ولا تسلكوا سبل الضلال، فتفرقكم وتبعدكم عن سبيل الله المستقيم. ذلكم التوجه نحو الطريق المستقيم هو الذي وصَّاكم الله به؛ لتتقوا عذابه بفعل أوامره، واجتناب نواهيه."},{"id":"943","jozz":"8","page":"149","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"9","aya_no":"154","aya_text":"ثُمَّ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ تَمَامًا عَلَى ٱلَّذِيٓ أَحۡسَنَ وَتَفۡصِيلٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمۡ يُؤۡمِنُونَ","aya_text_emlaey":"ثم آتينا موسى الكتاب تماما على الذي أحسن وتفصيلا لكل شيء وهدى ورحمة لعلهم بلقاء ربهم يؤمنون","aya_tafseer":"[154] ثم قل -أيها الرسول- لهؤلاء المشركين: إن الله تعالى هو الذي آتى موسى التوراة تماماً لنعمته على المحسنين من أهل ملته، وتفصيلاً لكل شيء من أمور دينهم، وهدى ودلالة على الطريق المستقيم ورحمة لهم؛ رجاء أن يصدِّقوا بالبعث بعد الموت والحساب والجزاء، ويعملوا لذلك."},{"id":"944","jozz":"8","page":"149","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"10","aya_no":"155","aya_text":"وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ فَٱتَّبِعُوهُ وَٱتَّقُواْ لَعَلَّكُمۡ تُرۡحَمُونَ","aya_text_emlaey":"وهذا كتاب أنـزلناه مبارك فاتبعوه واتقوا لعلكم ترحمون","aya_tafseer":"[155] وهذا القرآن كتاب أنزلناه على نبينا محمد -صلى الله عليه وسلم-، خيره كثير فاتبعوه فيما يأمر به وينهى عنه، واتقوا الله أن تخالفوا له أمراً؛ رجاء أن ترحموا فتنجوا من عذابه، وتظفروا بثوابه."},{"id":"945","jozz":"8","page":"149","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"11","aya_no":"156","aya_text":"أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ ٱلۡكِتَٰبُ عَلَىٰ طَآئِفَتَيۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَٰفِلِينَ","aya_text_emlaey":"أن تقولوا إنما أنـزل الكتاب على طائفتين من قبلنا وإن كنا عن دراستهم لغافلين","aya_tafseer":"[156] وأنزلنا هذا القرآن؛ لئلا تقولوا -يا كفار العرب-: إنما أُنزل الكتاب من السماء على اليهود والنصارى، وقد كنا عن قراءة كتبهم في شغل، ونحن ليس لنا بها علم ولا معرفة."},{"id":"946","jozz":"8","page":"149","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"12","line_end":"15","aya_no":"157","aya_text":"أَوۡ تَقُولُواْ لَوۡ أَنَّآ أُنزِلَ عَلَيۡنَا ٱلۡكِتَٰبُ لَكُنَّآ أَهۡدَىٰ مِنۡهُمۡۚ فَقَدۡ جَآءَكُم بَيِّنَةٞ مِّن رَّبِّكُمۡ وَهُدٗى وَرَحۡمَةٞۚ فَمَنۡ أَظۡلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِي ٱلَّذِينَ يَصۡدِفُونَ عَنۡ ءَايَٰتِنَا سُوٓءَ ٱلۡعَذَابِ بِمَا كَانُواْ يَصۡدِفُونَ","aya_text_emlaey":"أو تقولوا لو أنا أنـزل علينا الكتاب لكنا أهدى منهم فقد جاءكم بينة من ربكم وهدى ورحمة فمن أظلم ممن كذب بآيات الله وصدف عنها سنجزي الذين يصدفون عن آياتنا سوء العذاب بما كانوا يصدفون","aya_tafseer":"[157] ولئلا تقولوا -أيها المشركون-: لو أنَّا أُنزل علينا كتاب من السماء، كما أُنزل على اليهود والنصارى، لكنَّا أشدَّ استقامة على طريق الحق منهم، فقد جاءكم كتاب بلسانكم عربي مبين، وذلك حجة واضحة مِن ربكم وإرشاد إلى طريق الحق، ورحمةٌ لهذه الأمة. فلا أحد أشد ظلماً وعدواناً ممن كذَّب بحجج الله تعالى وأعرض عنها! فهؤلاء المعرضون سنعاقبهم عقاباً شديداً في نار جهنم؛ بسبب إعراضهم عن آياتنا، وصدِّهم عن سبيلنا."},{"id":"947","jozz":"8","page":"150","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"1","line_end":"4","aya_no":"158","aya_text":"هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَٰٓئِكَةُ أَوۡ يَأۡتِيَ رَبُّكَ أَوۡ يَأۡتِيَ بَعۡضُ ءَايَٰتِ رَبِّكَۗ يَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ قُلِ ٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ","aya_text_emlaey":"هل ينظرون إلا أن تأتيهم الملائكة أو يأتي ربك أو يأتي بعض آيات ربك يوم يأتي بعض آيات ربك لا ينفع نفسا إيمانها لم تكن آمنت من قبل أو كسبت في إيمانها خيرا قل انتظروا إنا منتظرون","aya_tafseer":"[158] هل ينتظر الذين أعرضوا وصدُّوا عن سبيل الله إلا أن يأتيهم ملك الموت وأعوانه لقبض أرواحهم، أو يأتي ربك -أيها الرسول- للفصل بين عباده يوم القيامة، أو يأتي بعض أشراط الساعة وعلاماتِها الدالَّةِ على مجيئها، وهي طلوع الشمس من مغربها؟ فحين يكون ذلك لا ينفع نفساً إيمانها، إن لم تكن آمنت من قبل، ولا يُقبَل منها إن كانت مؤمنة كَسْبُ عمل صالح إن لم تكن عاملة به قبل ذلك. قل لهم -أيها الرسول-: انتظروا مجيء ذلك؛ لتعلموا المحق من المبطل، والمسيء من المحسن، إنا منتظرون ذلك."},{"id":"948","jozz":"8","page":"150","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"4","line_end":"5","aya_no":"159","aya_text":"إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ إِنَّمَآ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفۡعَلُونَ","aya_text_emlaey":"إن الذين فرقوا دينهم وكانوا شيعا لست منهم في شيء إنما أمرهم إلى الله ثم ينبئهم بما كانوا يفعلون","aya_tafseer":"[159] إن الذين فَرَّقوا دينهم بعد ما كانوا مجتمعين على توحيد الله والعمل بشرعه، فأصبحوا فِرَقاً وأحزاباً، إنك -أيها الرسول- بريء منهم، إنما حكمهم إلى الله تعالى، ثم يخبرهم بأعمالهم، فيجازي من تاب منهم وأحسن بإحسانه، ويعاقب المسيء بإساءته."},{"id":"949","jozz":"8","page":"150","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"6","line_end":"7","aya_no":"160","aya_text":"مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَا وَهُمۡ لَا يُظۡلَمُونَ","aya_text_emlaey":"من جاء بالحسنة فله عشر أمثالها ومن جاء بالسيئة فلا يجزى إلا مثلها وهم لا يظلمون","aya_tafseer":"[160] من لقي ربه يوم القيامة بحسنة من الأعمال الصالحة فله عشر حسنات أمثالها، ومن لقي ربه بسيئة فلا يعاقب إلا بمثلها، وهم لا يظلمون مثقال ذرة."},{"id":"950","jozz":"8","page":"150","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"7","line_end":"9","aya_no":"161","aya_text":"قُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ دِينٗا قِيَمٗا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"قل إنني هداني ربي إلى صراط مستقيم دينا قيما ملة إبراهيم حنيفا وما كان من المشركين","aya_tafseer":"[161] قل -أيها الرسول- لهؤلاء المشركين: إنني أرشدني ربي إلى الطريق القويم الموصل إلى جنته، وهو دين الإسلام القائم بأمر الدنيا والآخرة، وهو دين التوحيد دين إبراهيم عليه السلام، وما كان إبراهيم عليه السلام من المشركين مع الله غيره."},{"id":"951","jozz":"8","page":"150","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"9","line_end":"10","aya_no":"162","aya_text":"قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"قل إن صلاتي ونسكي ومحياي ومماتي لله رب العالمين","aya_tafseer":"[162] قل -أيها الرسول- لهؤلاء المشركين: إن صلاتي، ونسكي، أي: ذبحي لله وحده، لا للأصنام، ولا للأموات، ولا للجن، ولا لغير ذلك مما تذبحونه لغير الله، وعلى غير اسمه كما تفعلون، وحياتي وموتي لله تعالى رب العالمين."},{"id":"952","jozz":"8","page":"150","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"10","line_end":"10","aya_no":"163","aya_text":"لَا شَرِيكَ لَهُۥۖ وَبِذَٰلِكَ أُمِرۡتُ وَأَنَا۠ أَوَّلُ ٱلۡمُسۡلِمِينَ","aya_text_emlaey":"لا شريك له وبذلك أمرت وأنا أول المسلمين","aya_tafseer":"[163] لا شريك له في ألوهيته ولا في ربوبيته ولا في أسمائه وصفاته، وبذلك التوحيد الخالص أمرني ربي جل وعلا، وأنا أول مَن أقرَّ وانقاد لله مِن هذه الأمة."},{"id":"953","jozz":"8","page":"150","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"11","line_end":"13","aya_no":"164","aya_text":"قُلۡ أَغَيۡرَ ٱللَّهِ أَبۡغِي رَبّٗا وَهُوَ رَبُّ كُلِّ شَيۡءٖۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","aya_text_emlaey":"قل أغير الله أبغي ربا وهو رب كل شيء ولا تكسب كل نفس إلا عليها ولا تزر وازرة وزر أخرى ثم إلى ربكم مرجعكم فينبئكم بما كنتم فيه تختلفون","aya_tafseer":"[164] قل -أيها الرسول-: أغير الله أطلب إلهاً، وهو خالق كل شيء ومالكه ومدبره؟ ولا يعمل أي إنسان عملاً سيئاً إلا كان إثمه عليه، ولا تحمل نفس آثمة إثم نفس أخرى، ثم إلى ربكم معادكم يوم القيامة، فيخبركم بما كنتم تختلفون فيه من أمر الدين."},{"id":"954","jozz":"8","page":"150","sura_no":"6","sura_name_en":"Al-An‘ām","sura_name_ar":"الأنعَام ","line_start":"13","line_end":"15","aya_no":"165","aya_text":"وَهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ","aya_text_emlaey":"وهو الذي جعلكم خلائف الأرض ورفع بعضكم فوق بعض درجات ليبلوكم في ما آتاكم إن ربك سريع العقاب وإنه لغفور رحيم","aya_tafseer":"[165] والله سبحانه هو الذي جعلكم تخلُفون مَن سبقكم في الأرض بعد أن أهلكهم الله، واستخلفكم فيها؛ لتعمروها بعدهم بطاعة ربكم، ورفع بعضكم في الرزق والقوة فوق بعض درجات؛ ليبلوكم فيما أعطاكم مِن نعمه، فيظهر للناس الشاكر من غيره. إن ربك سريع العقاب لمن كفر به وعصاه، وإنه لغفور لمن آمن به وعمل صالحاً وتاب من الموبقات، رحيم به، والغفور والرحيم اسمان كريمان من أسماء الله الحسنى."}]
